quests[31279] = { id = 31279, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alles, was ich übers Kochen weiß", description = "Ich bin so froh, dass Euch mein Essen schmeckt. Wärt Ihr vielleicht an den Rezepten interessiert? Falls ja, solltet Ihr sie aus erster Hand von meinen Lehrern vom Halbhügelmarkt lernen. Alles, was ich über die Küche weiß, habe ich bei ihnen gelernt.\n\nUnd wenn Ihr sowieso in diese Gegend kommt, könntet Ihr dann vielleicht Sungshin Eisentatz diese Nachricht überbringen? Sie war meine Lieblingslehrerin. Ich vermisse sie, und ich möchte, dass sie das auch weiß.", sourceObjective = "Überbringt Sungshin Eisentatz den Brief. Sie unterrichtet auf dem Halbhügelmarkt.", progress = "Ihr habt einen Brief für mich?", completion = "Oh, wie aufmerksam. Ich höre immer sehr gerne von meinen ehemaligen Schülern.", sourceObjectiveStatus = "unverified-source-field" }
quests[31280] = { id = 31280, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wie man kocht", description = "Es gibt viele Arten, zu kochen, und jede Methode erschafft einzigartige Gerichte. Die pandarischen Wege des Kochens sind der Weg des Grills, des Woks, des Topfes, des Dampfgarers, des Ofens und des Brauens. Es scheint, als ob Ihr durch Eure Erfahrungen in fernen Ländern bereits die Grundlagen eines jeden Weges beherrscht. Falls Ihr wünscht, noch weiter ausgebildet zu werden, sprecht mit meinen Geschwistern und erlernt das erste fortgeschrittene Rezept, dass jeder von ihnen lehrt. Findet heraus, welcher Weg am besten zu Euch passt.", sourceObjective = "Erlernt die Rezepte für gegrilltes Tigersteak, gebratenen Reis nach Jadewaldart, verwirbelte Nebelsuppe, Garnelenklößchen, Wildgeflügelbraten und Ginsengtee von den Meistern auf dem Halbhügelmarkt.", sourceObjectiveStatus = "unverified-source-field" }
quests[31281] = { id = 31281, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ihr wollt also Koch werden…", description = "Ihr wollt <Koch/Köchin> werden? Wenn Ihr wirklich Eure volle Hingabe beweist, kann ich Euer verborgenes Potenzial verwirklichen, egal, wie unerfahren Ihr seid.\n\nWenn Ihr etwas von mir lernen wollt, dann zeigt mir, dass Ihr zumindest einfachen Anweisungen folgen könnt. Lernt, wie man einen Pfirsich in Scheiben schneidet und zeigt mir dann, was Ihr gelernt habt. Ich kann Euch frische pandarische Pfirsiche zu einem guten Preis verkaufen.", sourceObjective = "Erlernt das Rezept für einen Pfirsich in Scheiben von der Weiserin der Wege und bereitet ihr 5 von ihnen zu.", progress = "Beweist mir, dass Ihr Anweisungen folgen könnt.", completion = "Nun gut. Ihr seid in der Lage, etwas zu lernen. Ich kann Euch viel beibringen, und ich habe die meisten Zutaten, die Ihr braucht, um etwas zu lernen. Ihr könnt Euch von mir unterrichten lassen.", sourceObjectiveStatus = "unverified-source-field" }
quests[31285] = { id = 31285, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Frühlingsbummler", description = "Wer auf eine Begegnung mit ein paar Saurok verzichten möchte, sollte die Uralte Passage nicht zu Fuß bereisen.\n\nIch mache Euch ein Angebot: Eierschale und ich wollten gerade flussaufwärts nach Binan aufbrechen. Sollen wir Euch mitnehmen?", sourceObjective = "Überlebt eine Fahrt mit der Frühlingsbummler.", completion = "Puh... Das wäre geschafft. Willkommen in Binan.", sourceObjectiveStatus = "unverified-source-field" }
quests[31286] = { id = 31286, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beraubung der Räuber", description = "Ah, {class}. Ich hätte da gerade Verwendung für Eure Fähigkeiten.\n\nOben an der Straße wurde ein Konvoi von einer Bande marodierender Saurok angegriffen. Die Räuber haben ein paar... Waren... entwendet, die Madame Goya veräußern wollte.\n\nEs gleicht einem Sakrileg, Madame Goya zu bestehlen.\n\nWenn es Euch gelingen sollte, diese Waren zurückzuholen, werde ich Euch gerne einen Finderlohn zahlen.", sourceObjective = "Holt 7 Schwarzmarktwaren zurück.", progress = "Die Saurok sind normalerweise nicht so dreist.", completion = "Ah, unsere Waren. Madame Goya wird sehr zufrieden sein. Ihr könnt Euch ihrer Dankbarkeit gewiss sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[31287] = { id = 31287, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erziehungsprogramm für die Saurok", description = "Die Lenzstraße untersteht dem Schutz unserer verehrten Madame Goya.\n\nUnd um diese Tatsache zu verdeutlichen, scheinen die Saurok im Hassschuppenbau nordöstlich von hier ein \"Erziehungsprogramm\" zu benötigen. Wir haben sie bereits in der Vergangenheit gewarnt, aber offensichtlich haben sie leider ein kurzes Gedächtnis.\n\nBegebt Euch zu ihrem Bau im Nordosten und findet ihren Schamanenanführer. Wenn es Euch gelingt, ihn zu liquidieren, ist Euch der Dank unserer verehrten Dame gewiss - neben einem angemessenen Kopfgeld, versteht sich.", sourceObjective = "Liquidiert Saugfinger.", completion = "Die Aufgabe wurde erfüllt und Schuld muss bezahlt werden. Hier ist Eure Belohnung. Seid Euch unseres Dankes gewiss.", sourceObjectiveStatus = "unverified-source-field" }
quests[31288] = { id = 31288, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Forschungsprojekt: Die Mogudynastien", description = "Ah, <ein Entdecker/eine Entdeckerin> - Ihr kommt gerade recht. Ich stehe nämlich kurz davor, einige der dunklen Geheimnisse der Mogu aufzudecken.\n\nAllerdings nicht alle. Sie haben nämlich viele dunkle Geheimnisse. Aber zumindest bin ich ganz kurz davor, zumindest eines der vielen dunklen Geheimnisse aufzudecken.\n\nWenn Ihr also auf Euren Reisen über Mogufragmente stolpert, dann bringt sie mir. Ich werde mich dafür auch erkenntlich zeigen.", sourceObjective = "Bergt 20 archäologische Fragmente der Mogu.", progress = "Es ist gefährlich, die Vergangenheit zu ignorieren.", completion = "Ah! Das sind ein paar sehr schöne Stücke. Wirklich sehr schön. Ich danke Euch, Abenteurer.", sourceObjectiveStatus = "unverified-source-field" }
quests[31289] = { id = 31289, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Forschungsprojekt: Das Pandaren-Reich", description = "Ah, gut, dass Ihr gerade da seid, <Abenteurer/Abenteurerin>. Meine Tochter und ich erforschen nämlich gerade die Historie unseres Volkes und kommen an einer Stelle nicht so recht weiter.\n\nSolltet Ihr auf antiquarische Pandarenobjekte stoßen, dann bringt sie uns bitte. Wir würden einen großen Vorteil aus solchen zusätzlichen Informationen ziehen können.", sourceObjective = "Bergt 20 archäologische Fragmente der Pandaren.", sourceObjectiveStatus = "unverified-source-field" }
quests[31291] = { id = 31291, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Geheimnisse der Vergangenheit", description = "Seid Ihr daran interessiert, auch <ein Lehrensucher/eine Lehrensucherin> zu werden? Dann stellt Euch auf viel Graben und viel Lesen und noch mehr Graben und noch mehr Lesen ein.\n\nIch verbringe ganze Tage damit, auf zerbrochene Vasen zu starren und zu überlegen, wie man sie wieder zusammensetzen kann.\n\nAber probiert es ruhig aus. Wenn Ihr eines der Artefakte aus Pandaria vollständig zusammensetzen könnt, wären wir Euch verbunden, wenn Ihr dieses Wissen mit uns teilen könntet.", sourceObjective = "Setzt 1 Artefakt aus Pandaria wieder zusammen.", progress = "Ich frage mich, ob ich wirklich genug Talent dafür habe.", completion = "Großartig! Ihr habt die Teile fast nahtlos zusammenfügen können. Die Qualität dieser Restaurierung ist ja überragend.\n\nWie habt Ihr das hinbekommen?", sourceObjectiveStatus = "unverified-source-field" }
quests[31293] = { id = 31293, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mogu keine guten Gäste", description = "Leven hat Rook hierher geschickt, um Mogu aufzuhalten. Sind aber mehr Mogu als Rook töten kann.\n\nHelft Ihr? Rook erzählt Leven auch von Eurer Hilfe. Versprochen.", sourceObjective = "Tötet 8 Shao-Tien-Angreifer in Nebelhauch.", completion = "Rook kommt jetzt mit restlichen Mogu klar. Danke für Hilfe, guter Mann.", sourceObjectiveStatus = "unverified-source-field" }
quests[31294] = { id = 31294, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Guo-Lai-Ruinen", description = "Ich danke Euch von ganzem Herzen für Eure Hilfe. Anji wartet in den Guo-Lai-Ruinen im Nordwesten auf Euch.\n\nBitte begebt Euch dorthin. Und möge Euch Euer Mut niemals verlassen, <junger/junge:c> {class}.", sourceObjective = "Sprecht mit Anji Herbstlicht bei den Guo-Lai-Ruinen.", completion = "Che hat Euch geschickt? Gut, dass Ihr da seid.\n\nIn den Ruinen wimmelt es nur so von Dingen, die zertreten werden wollen.", sourceObjectiveStatus = "unverified-source-field" }
quests[31295] = { id = 31295, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mogu in den Guo-Lai-Ruinen", description = "Danke für Eure Hilfe.\n\nIch würde Euch gern weiterhin Gesellschaft leisten, aber Leven führt einen Angriff gegen die Mogu in den Guo-Lai-Ruinen nordwestlich von hier. Und er kann jeden fähigen Kämpfer gebrauchen.\n\nMögen die Himmlischen Euch beschützen, <junger Mann/junge Dame>.", sourceObjective = "Sprecht mit Leven Morgenklinge in den Guo-Lai-Ruinen.", completion = "Gut, dass Ihr da seid.\n\nIch weiß nicht, wie die Mogu so viele Truppen versammeln konnten, aber wir müssen sie angreifen, bevor sie ihren Vorstoß wagen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[31296] = { id = 31296, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Guo-Lai-Ruinen", description = "Die Dorfbewohner scheinen in Sicherheit zu sein und die Mogu werden langsam zurückgedrängt. Den Rest sollten wir selbst erledigen können. Danke für Eure freundliche Hilfe, {name}.\n\nAnji hat heute morgen eine Gruppe zur Erkundung und Befreiung der Guo-Lai-Ruinen in den Nordwesten geführt. Sicherlich könnte sie dort jemanden mit Euren Talenten gebrauchen. Ihr solltet sie aufsuchen.", sourceObjective = "Sprecht mit Anji Herbstlicht bei den Guo-Lai-Ruinen.", sourceObjectiveStatus = "unverified-source-field" }
quests[31297] = { id = 31297, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Garnison der Untergehenden Sonne", description = "Die Mogu werden diesen Angriff nicht lange aufrechterhalten können. Von jetzt an sollten wir die Situation in den Griff bekommen. Danke für Eure freundliche Hilfe.\n\nAber vielleicht könnt Ihr ja Anji im Ausbildungslager der Untergehenden Sonne aufsuchen? Sie ist damit beauftragt, die Pandarenrekruten auszubilden. Und Ihr könntet ihnen wohl auch noch ein oder zwei Dinge beibringen.", sourceObjective = "Sprecht mit Anji Herbstlicht im Ausbildungslager der Untergehenden Sonne.", completion = "Mit Euch kann man arbeiten. Dann zeigen wir diesen Auszubildenden mal, wie ein echter {class} kämpft.", sourceObjectiveStatus = "unverified-source-field" }
quests[31302] = { id = 31302, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bereit für Großes", description = "Ihr scheint Euch in der Küche ziemlich gut auszukennen. Zeigt mir, was Ihr könnt, indem Ihr 5 Schüsseln Milchreis zubereitet.", sourceObjective = "Bereitet 5 Schüsseln Milchreis zu und gebt sie der Gewährerin der Einblicke.", progress = "Ich glaube, Ihr habt das Zeug zu einem großen Koch, doch erst der Milchreis wird meine Einschätzung bestätigen.", completion = "Ihr seid bereit. Ihr seid nun ein Zen-Meisterkoch.", sourceObjectiveStatus = "unverified-source-field" }
quests[31303] = { id = 31303, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Siegel ist zerbrochen", description = "<Cho sieht Euch ungläubig an.>\n\nIch... Ich glaubte, Sha von dieser Größe seien ein Mythos - wir alle glaubten das. Wir hielten sie für ein Ammenmärchen, um den Kindern das Kämpfen auszutreiben.\n\nAber für Geplauder bleibt jetzt keine Zeit. Diese Risse, sie nähren es... und machen es jeden Augenblick stärker!\n\nIch muss diese Schriftrollen aus meinen Familienarchiven untersuchen. Ihr, nehmt diese Kanone und reitet Mishi.\n\nIhr müsst einen Weg finden, diesem Schrecken zu begegnen, der auf uns losgelassen wurde!", sourceObjective = "Versiegelt 12 Risse des Sha und verbannt das Sha des Zweifels.", completion = "Ich muss viele Nachforschungen in nur wenig Zeit erledigen.\n\nDie Nachricht des Kaisers warnte nur vor einer einzigartigen Gefahr, die diesem Land Krieg bringen würde - dieses… Sha.\n\nLeider ist die Zeit, seinen Rat zu beherzigen, bereits vorüber. Wie wir nun dieser Krise ein Ende bereiten können, darüber schweigt das Omen des Kaisers.", sourceObjectiveStatus = "unverified-source-field" }
quests[31305] = { id = 31305, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Weg des Grills", description = "Wenn Ihr Essen kocht wollt, dass Euch stärker macht, sucht den Meister des Grills auf. Bereitet für ihn ein Hühnchenspieß mit Erdnusssoße zu, um ihm zu zeigen, dass Ihr die Grundlagen beherrscht.", sourceObjective = "Bereitet ein Hühnchenspieß mit Erdnusssoße zu und gebt es dem Meister des Grills.", sourceObjectiveStatus = "unverified-source-field" }
quests[31306] = { id = 31306, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pfad des Unwissenden", description = "Ich bin mir ziemlich sicher, dass Euer Pandaren-Freund eine Ahnung hat, wonach die Mogu eigentlich suchen.\n\nEr hat sich vor ein paar Tagen ohne Bergführer ins Gebirge aufgemacht und gesagt, dass nur Ihr ihm folgen sollt. Er hatte sich sehr klar ausgedrückt:\n\n\"<Der/Die:c> {class} muss diesen Pfad allein beschreiten, vollkommen konzentriert auf <seine/ihre> eigenen Gedanken. <Er/Sie> soll jedem Schrein die Ehre erweisen, bevor wir uns am Gipfel wiedersehen.\"\n\nDer Pfad beginnt gleich nordwestlich des Lagers und ist durch Flaggen gekennzeichnet. Aber passt gut auf Euch auf! Der Pfad des Unwissenden ist selbst an den harmlosesten Tagen noch gefährlich.", sourceObjective = "Bewältigt den Pfad des Unwissenden, um Euch mit dem Lehrensucher Cho zu treffen. Macht an allen Schreinen entlang des Weges Halt, um Euch dort auf Eure Gedanken zu konzentrieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[31308] = { id = 31308, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erste Erfahrungen", description = "Da Ihr nun <Tierausbilder/Tierausbilderin> seid, ist es an der Zeit, Euer Können auf die Probe zu stellen!\n\nGeht hinaus in den Wald und beginnt einen Kampf mit einem Kampfhaustier. Vergesst nicht, Eure Fertigkeit 'Haustiere aufspüren' einzusetzen, damit Ihr kampfbereite Haustiere auf der Minikarte sehen könnt. Kommt wieder zu mir, nachdem Ihr gewonnen habt, dann setzen wir Eure Ausbildung fort. Viel Glück!", sourceObjective = "Gewinnt einen Haustierkampf.", sourceObjectiveStatus = "unverified-source-field" }
quests[31309] = { id = 31309, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf dem Wege der Besserung", description = "Nachdem Ihr nun einen Kampf gewonnen habt, müssen wir Eure Haustiere heilen, damit sie wieder einsatzbereit sind! Sucht unsere Stallmeisterin Erma auf, um Eure Haustiere zu heilen und wiederzubeleben.", sourceObjective = "Stattet Erma der Stallmeisterin einen Besuch ab und heilt Eure Tiere vollständig.", sourceObjectiveStatus = "unverified-source-field" }
quests[31311] = { id = 31311, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weg des Grills", description = "Der Weg des Grills der Pandaren bringt Gerichte hervor, die Eure körperliche Stärke erhöhen. Bringt einige rohe Tigersteaks zum Meister des Grills und er wird Euch beibringen, was Ihr mit ihnen anstellen könnt. Es gibt viele Tiger im Jadewald und der Krasarangwildnis, aber Ihr könnt sie auch anderswo finden.", sourceObjective = "Bringt 5 rohe Tigersteaks zum Meister des Grills.", progress = "Wenn Ihr den Weg des Grills lernen wollt, bringt mir zunächst ein paar rohe Tigersteaks.", completion = "Exzellente Stücke.", sourceObjectiveStatus = "unverified-source-field" }
quests[31312] = { id = 31312, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die alte Karte", description = "Das alte, verblichene Leder fällt fast auseinander, ist aber immer noch lesbar.\n\nJemand scheint eine Art Karte darauf gezeichnet zu haben... und die folgenden Worte:\n\n\nTief in dem Tal, wo die Vier Winde wehen,\nlacht die Jungfer hinter ihrem güldenen Fächer.\nZu Füßen der Treppe ihrer Ahnen,\nflüstert sie ihr Geheimnis in die hallende Nacht.", sourceObjective = "Zeigt Fischi Rohrroder am Rohrkolbensee oder auf dem Halbhügelmarkt im Tal der Vier Winde die Karte.\n\nBereitgestellter Gegenstand:", completion = "Boah! Ich glaube, Ihr habt sie gefunden, {name}! Ihr habt die Karte zum Schatz des alten Distel gefunden!", sourceObjectiveStatus = "unverified-source-field" }
quests[31313] = { id = 31313, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nur eine Volkserzählung", description = "Was!?! Das ergibt doch überhaupt keinen Sinn! <Fischi macht einen enttäuschten Eindruck.>\n\nWas soll dieses ganze Kauderwelsch von einer Jungfer, einem Ahnen und irgendeiner Treppe?\n\nIch werde daraus einfach nicht schlau... Ihr vielleicht?\n\nNun, es gibt hier eine Menge Leute, die sehr viel älter als Ihr und ich sind, {name}.\n\nKönnt Ihr vielleicht mit den Bewohnern von Halbhügel sprechen? Ich könnte wetten, dass sie etwas wissen!", sourceObjective = "Sprecht mit Korntrenner Pei, Steinmeißler Mac, Mama Min und dem alten Herrn Weißbart.", completion = "Natürlich! Das ergibt absolut Sinn. Der Schatz muss also an der Stelle liegen, wo der See an die Berge angrenzt!", sourceObjectiveStatus = "unverified-source-field" }
quests[31314] = { id = 31314, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Schatz des alten Distel", description = "Na Donnerwetter! Das entwickelt sich ja zu einer waschechten Schatzsuche!\n\nEs muss im Norden eine Art Eingang oder Öffnung geben... an der Stelle, wo die Berge und der Rohrkolbensee zusammentreffen.\n\nWir treffen uns beim Eingang! Dieser Schatz gehört uns!", sourceObjective = "Findet den Höhleneingang und holt Euch den Schatz des alten Distel.", progress = "Wenn ich's nicht mit eigenen Augen sehen würde, wär' es kaum zu glauben!", completion = "Der Deckel der Kiste lässt sich durch einen leichten Schubser herunterschieben. Ihr blickt in die Kiste...", sourceObjectiveStatus = "unverified-source-field" }
quests[31315] = { id = 31315, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Kernlanderbe", description = "Ganz unten in der Schatzkiste findet Ihr einige Schriftrollen und einen weichen Lederbeutel mit Samen.\n\nWenn Ihr die Schriftrollen ausbreitet, seht Ihr darauf detaillierte Notizen zum Landbau, Zeichnungen von Pflanzen, Zahlen und Berechnungen, Positionen nahe gelegener Wasserquellen und einige andere Informationen.\n\nVielleicht interessiert sich ja jemand bei dem Bund der Ackerbauern dafür.", sourceObjective = "Bringt den Almanach des alten Distel zu Saatwärterin Shing Sing in Halbhügel im Tal der Vier Winde.", progress = "Was habt Ihr da?", completion = "Ach ja, ich kenne die Geschichte des alten Distel ziemlich gut, {race}.\n\nÜber seine Schatzsuche gibt es jede Menge verrückte Erzählungen.\n\nTatsächlich war er aber so etwas wie ein Einsiedler... exzentrisch und dabei auch ein hervorragender Bauer.\n\nAn seinem Lebensabend zog er sich in die Berge zurück und ward nie wieder gesehen.\n\nEr war trotz allem einfach nur ein Mann, der sein Leben lebte, und wie es scheint, habt Ihr sein Vermächtnis gefunden.\n\nErzählt Fischi nicht die Wahrheit. Manche der besten Geschichten sind größer als das Leben, von dem sie erzählen.", sourceObjectiveStatus = "unverified-source-field" }
quests[31316] = { id = 31316, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Julia, die Tierzähmerin", description = "Wie ich sehe, habt Ihr Eure Fertigkeiten im Haustierkampf verbessert, {name}. Ich glaube, Ihr seid reif für eine echte Herausforderung.\n\nIhr findet Julia Stevens in den Weinbergen der Maclures, südlich von Sturmwind. Sie ist eine aufstrebende Wildtierzähmerin und ich finde, Ihr solltet Euch mit ihr im Kampf messen!", sourceObjective = "Besiegt Julia Stevens in einem Haustierkampf.", progress = "Wie sieht es mit Eurer Mannschaft aus? Ich habe schon zwei Schlangen!", completion = "Ihr könnt besser mit diesen Tierchen umgehen, als ich dachte!", sourceObjectiveStatus = "unverified-source-field" }
quests[31319] = { id = 31319, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Notfallplan", description = "Eure Kameraden haben sich in unseren Landen eine neue Heimat errichtet und einen gefährlichen Zwist mit sich gebracht.\n\nDas volle Ausmaß der Vernichtung können wir hier noch nicht abschätzen, doch bereits jetzt ist es… unaussprechlich.\n\nUnd doch, Eure Freunde aus Rachegefühlen sich selbst zu überlassen, würde unserer Art zu leben widersprechen. Jeder, der jetzt noch am Leben ist, ist zweifelslos verwundet und bedarf dringend Hilfe.\n\nDieses Feuerwerk war eigentlich dazu gedacht, die Fertigstellung der Statue zu feiern. Benutzt es in der Nähe Eurer Kameraden, um Mishi ein Zeichen zu geben, und sie wird sie in Sicherheit bringen.", sourceObjective = "Benutzt Chos Feuerwerk in der Nähe von Admiral Taylor, Mishka und Sully.", completion = "Mit meinen Gedanken bin ich bei Euren gefallenen Begleitern, Reisender.\n\nMögen ihre Wunden gut heilen.", sourceObjectiveStatus = "unverified-source-field" }
quests[31320] = { id = 31320, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Einen Drink für einen Fisch?", description = "Heeee, Ko...Kollege... Wie läuft's denn so? Wo...wollt Ihr 'nem Ji...inyu nich' was zu trink'n ka...kauf'n?", sourceObjective = "Bringt Jogu dem Betrunkenen 1 Vier-Winde-Soju. Vier-Winde-Soju kann von den meisten Schankkellnern in Pandaria erworben werden.", progress = "Durstig...", completion = "Da...anke, K...Kumpel.", sourceObjectiveStatus = "unverified-source-field" }
quests[31321] = { id = 31321, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Runde für einen Fisch?", description = "Heyyy, das is' doch mei... <mein Freund/meine Freundin>!\n\nIhr ha...abt mich wohl hier ru...umhäng'n seh'n. Ihr mü...müsst a...aber wiss'n, dass ich nich' be...betrunk'n bin.\n\nIch mein'... se...seht mich doch mal an! Nü...nüchtern wie ein Sü...Süßwasserfisch!\n\nKlar, ich ertränk' meine So...org'n hier u...und da mal in 'nem gu...ut'n Gebräu, a...aber 'nen Jinyu kri...iegt Ihr nich' besoff'n! Kö...Könntet gena...ausogut versuch'n, 'n Fi...isch zu ertränk'n!\n\nNö, vo...von dem Gebr...äu werd' ich immer nur schl...schläfrig. Un' da...ann hab' ich Visio'n von der Zu...ukunft.\n\n\n\nJe stä...ärker das Gebräu, desto stä...ärker meine Träu...Träume! Bringt m...mir was zu schluck'n, un' i...ich schuld' Euch w...was.", sourceObjective = "Bringt Jogu dem Betrunkenen 5 Flaschen Pandarenpflaumenwein. Pandarenpflaumenwein kann von den meisten Schankkellnern in Pandaria erworben werden.", progress = "Was meint Ihr mit \"Ihr lallt wie ein Betrunkener\"? S...So sprech' ich i...immer!", completion = "Oooh, da...das is' gutes Zeug...", sourceObjectiveStatus = "unverified-source-field" }
quests[31322] = { id = 31322, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Fässchen für einen Fisch?", description = "Meine Träu... meine Träume si...ind in letzter Zeit so... fa...arblos, {race}.\n\nIch bra...auch' was Kräftiges, damit ich wieder... a...auf die B...Beine komm'!\n\nIch hab' gehört, e...es gibt da so 'nen le...leckeren Trunk, den die Leu...Leute heutzutage zusamm'nbrau'n.\n\nEs heißt Ja...Jadehex'nbräu.\n\nWürd' ich ge...ern mal... probier'n.", sourceObjective = "Bringt Jogu dem Betrunkenen 10 Flaschen Jadehexenbräu. Jadehexenbräu kann durch Kochkunst hergestellt werden.", progress = "Glück gehabt?", completion = "Oooh, da...das haut ja zi...iemlich rein! Ich we...werd' schon ganz schl...schläfrig...", sourceObjectiveStatus = "unverified-source-field" }
quests[31323] = { id = 31323, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Brauerei für einen Fisch?", description = "Allso, {name}, damit ich auch in Zu...ukunkft noch Visionen ha...ab'n kann, brauch' ich... meine eig'ne Bra...auerei.\n\n...\n\nIch m...mach doch nur Spaß! Hättet ma...al Euren Gesi... Gesichtsausdruck seh'n soll'n! Einfach he...errlich... hicks!\n\nJed'nfalls hab' ich von n...nem Gebräu gehört, da...as anders sein soll als alle and'ren. Das... wü...ürd' ich gern mal... probier'n.\n\nHabt Ihr schon vom... Wa...ahnsinnig'n Brauerfrühstück gehört? Wenn... Wenn Ihr mir von de...em Zeug was bringt, sind wir Fr...Freunde fürs Leb'n.", sourceObjective = "Bringt Jogu dem Betrunkenen 20 wahnsinnige Brauerfrühstücke. Wahnsinnige Brauerfrühstücke können durch Kochkunst hergestellt werden.", progress = "Habt Ihr es versucht?", completion = "Danke, {name}! Die we...erd' ich mir fü...ür 'n schlecht'n Ta...ag... zur Seite leg'n... hicks!", sourceObjectiveStatus = "unverified-source-field" }
quests[31324] = { id = 31324, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Familiengeheimnisse", description = "Unsere geheimen Rezepte! Ich habe sie gerade zusammengetragen, doch dann... Ho-zen?\n\n<Tantchen sieht sehr verwirrt aus.>\n\nWie soll Gao so denn etwas zusammenbrauen? Er braucht diese Rezepte, sonst gibt es noch eine Katastrophe!", sourceObjective = "Sammelt 5 Geheimnisse der Sturmbräus.", progress = "Oh, hallo!", completion = "Ho ho, was ist denn das?\n\n<Onkel Gaos fetter Bräubauch schwabbelt beim Anblick der Familienrezepte freudig auf und ab.>\n\nAch, ich wusste doch, dass ich zu viel Mais benutze!", sourceObjectiveStatus = "unverified-source-field" }
quests[31325] = { id = 31325, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine sehr schöne Halskette", description = "Diese wunderschöne Halskette wurde teilweise von den schmutzigen Händen eines Ho-zen verschmiert.\n\nEs gibt im Tal nur eine Person, die ein so schönes Schmuckstück besitzen könnte.", sourceObjective = "Bringt die Halskette zu Tina Lehmkrall in Haohans Haus oder zum Halbhügelmarkt im Tal der Vier Winde.\n\nBereitgestellter Gegenstand:", completion = "Oh, das ist ja meine Lieblingshalskette! Mir war gar nicht bewusst, dass ich sie verloren hatte! Danke, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[31326] = { id = 31326, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tinas elegante Tiara", description = "Es ist eine blendende Diamantentiara. Wer im Tal könnte wohl reich genug sein, um ein solches Schmuckstück zu besitzen?\n\nWer auch immer es ist, er oder sie dürfte eine nette Belohnung herausspringen lassen.", sourceObjective = "Bringt die elegante Tiara zu Tina Lehmkrall in Haohans Haus oder zum Halbhügelmarkt im Tal der Vier Winde.\n\nBereitgestellter Gegenstand:", completion = "Oh, meine Tiara! Ich hatte sie verloren, aber wo um alles in der Welt habt Ihr sie nur gefunden?", sourceObjectiveStatus = "unverified-source-field" }
quests[31327] = { id = 31327, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ärger aus dem Fass", description = "In der Brauerei treiben Ho-zen ihr Unwesen und... wer weiß was noch. Ich bin sicher, dass die Brauer in Schwierigkeiten stecken.\n\nWärt Ihr vielleicht so nett, herauszufinden, was da vor sich geht, <mein Freund/meine Liebe>?", sourceObjective = "Tötet Yan-Zhu den Dekantierten.", completion = "Eine riesige, aus Gebräu entstandene Kreatur?! Wer hätte je gedacht, dass es so etwas geben kann?\n\nDanke, dass Ihr Gao vor seinen eigenen fehlgeleiteten Brauereiexperimenten gerettet habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[31328] = { id = 31328, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein exquisiter Ohrring", description = "Ihr nehmt den Ohrring aus dem pelzigen Ohr der Kreatur. Wie es scheint, hatte der Bursche beim Tragen dieses baumelnden Rings eine Menge Spaß. ZU VIEL Spaß.\n\nVielleicht hätte die Besitzerin dieses anmutigen Schmuckstücks es gern zurück. Ihr müsst ihr ja nicht sagen, wo Ihr es gefunden habt... oder wer es getragen hat.", sourceObjective = "Bringt den exquisiten Ohrring zu Tina Lehmkrall in Haohans Haus oder zum Halbhügelmarkt im Tal der Vier Winde.\n\nBereitgestellter Gegenstand:", completion = "Oh, mein Ohrring! Aber, er passt ja genau zu dem, den ich heute trage!\n\n<Tina steckt sich den Ohrring ins Ohr.>\n\nIch danke Euch, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[31329] = { id = 31329, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine wunderschöne Brosche", description = "Diese sehr alte antike Brosche wurde mit viel Liebe zum Detail gefertigt und in einen filigranen Rahmen eingefasst. Sie sieht sehr wertvoll aus.\n\nEs gibt nur eine Person, die immer wieder Schmuckstücke an pelzige Straßendiebe verliert, und sie würde dieses Erbstück vermutlich sehr gerne zurückhaben.", sourceObjective = "Bringt die wunderschöne Brosche zu Tina Lehmkrall in Haohans Haus oder zum Halbhügelmarkt im Tal der Vier Winde.\n\nBereitgestellter Gegenstand:", completion = "Die Brosche meiner Großmutter! Oh, was für ein Glück, dass Ihr sie gefunden habt! Es ist ein wertvolles Familienstück.", sourceObjectiveStatus = "unverified-source-field" }
quests[31331] = { id = 31331, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Anleitung zur Questerstellung", description = "Juchu! Ihr dürft eine Schnitzeljagdquest erstellen! Findet heraus, was als Nächstes zu tun ist.", sourceObjective = "Erstellt eine Schnitzeljagdquest.", sourceObjectiveStatus = "unverified-source-field" }
quests[31332] = { id = 31332, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lektion 1: Pfirsich in Scheiben", description = "Ich brenne schon richtig auf den Beginn meiner Ausbildung. Wir fangen mit einem Pfirsich in Scheiben an, richtig?", sourceObjective = "Besorgt Euch 5 Pandarenpfirsiche für Nomis Kochstunde.", progress = "Ich will so gern Koch werden, die anderen Kinder haben aber schon vor zwei Monaten angefangen. Ohne Eure Hilfe hole ich sie niemals ein.", completion = "Hier, fertig! Und, wie habe ich mich geschlagen?", sourceObjectiveStatus = "unverified-source-field" }
quests[31333] = { id = 31333, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lektion 2: Fertignudeln", description = "Fertignudeln sind ja nicht so schwer zu kochen, oder?", sourceObjective = "Besorgt 5 Portionen Fertignudeln für Nomis Kochlektion.", progress = "Es ist so leicht, die Nudeln zu verkochen!", completion = "Hier, fertig! Und, wie habe ich mich geschlagen?", sourceObjectiveStatus = "unverified-source-field" }
quests[31334] = { id = 31334, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lektion 3: Gerösteter Trockenfisch", description = "Das Kochen ist schwieriger, als ich dachte. Es ist so schnell etwas verbrannt.", sourceObjective = "Besorgt 5 Goldkarpfen für Nomis Kochlektion.", progress = "Hoffentlich verbrenne ich mich nicht. IIH!", completion = "Hier, fertig! Und, wie habe ich mich geschlagen?", sourceObjectiveStatus = "unverified-source-field" }
quests[31335] = { id = 31335, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lektion 4: Getrocknete Nadelpilze", description = "Mit Pilzen hab' ich's nicht so besonders... aber ich werde mein Bestes tun, mehr über sie zu lernen.", sourceObjective = "Besorgt 5 Nadelpilze für Nomis Kochlektion.", progress = "Igitt.", completion = "Hier, fertig! Und, wie habe ich mich geschlagen?", sourceObjectiveStatus = "unverified-source-field" }
quests[31336] = { id = 31336, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lektion 5: Stampfreiskuchen", description = "Ich liebe Reiskuchen. Ich werde mein Bestes tun, ganz besonders gute zu backen!", sourceObjective = "Besorgt Euch 5 Portionen Reis für Nomis Kochlektion.", progress = "Ich bin schon ganz gespannt, ob sie was werden!", completion = "Hier, fertig! Und, wie habe ich mich geschlagen?", sourceObjectiveStatus = "unverified-source-field" }
quests[31337] = { id = 31337, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Zeichen der Anerkennung", description = "Danke, dass Ihr Euch vergewissert habt, dass bei mir alles zum Besten steht! Ich konnte heute der Familie Eisentatz helfen, und man gestattete mir, Euch dies zu überbringen.", sourceObjective = "Nehmt Nomis Geschenk an.", sourceObjectiveStatus = "unverified-source-field" }
quests[31338] = { id = 31338, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein verlorenes Schäfchen", description = "Schäfchen, Chi-Chis wertvollstes Schaf, ist verschwunden!\n\nDas dumme Ding ist immer wieder vom Hof weggelaufen.\n\nDummes Schaf! Ich hab' überall gesucht, konnte es aber nicht finden.\n\nKönnt Ihr mir helfen, {race}?", sourceObjective = "Findet Schäfchen und bringt es zu Chi-Chi zurück.", progress = "Habt Ihr mein Schäfchen gefunden? Ach, und ich hab' mir solche Sorgen gemacht.", completion = "Oh, Ihr habt ihn gefunden! Danke!", sourceObjectiveStatus = "unverified-source-field" }
quests[31339] = { id = 31339, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schäfchen ist schon wieder weg", description = "Dieses dumme Schaf ist schon wieder abgehauen!\n\nKönnt Ihr es noch mal für mich suchen?", sourceObjective = "Findet Schäfchen und bringt ihn zu Chi-Chi zurück.", progress = "Ach, armes Schäfchen. Ist sicher ganz verängstigt und furchtbar allein...", completion = "Schäfchen, ich hab' mir ja solche Sorgen gemacht! Böses Schaf! Chi-Chi war ja so beunruhigt!", sourceObjectiveStatus = "unverified-source-field" }
quests[31340] = { id = 31340, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ach, Schäfchen...", description = "Seufz... Ihr habt es sicher erraten... Schäfchen ist fort... SCHON WIEDER.\n\nDummes Schaf! Macht mir immer so viel Ärger!\n\nIch muss Euch noch einmal um einen Gefallen bitten, aber ist garantiert das letzte Mal, versprochen.\n\nKönnt Ihr für mich nach Schäfchen suchen?", sourceObjective = "Findet Schäfchen.", completion = "Was? Schäfchen ist... fort?\n\n<Chi-Chis Lippen beginnen zu beben.>", sourceObjectiveStatus = "unverified-source-field" }
quests[31341] = { id = 31341, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Wolf im Schafspelz", description = "AAAARRRRRGGGHHHHH!!!! Dieser letzte Tropfen hat das Fass zum Überlaufen gebracht!\n\nDiese dummen Ho-zen auf dem Berg haben mein SCHÄFCHEN umgebracht!\n\nIch weiß genau, wer es war, und diesmal werde ich mich RÄCHEN.\n\nWenn Ihr mir helfen wollt, legt diesen alten Schafspelz an.\n\nVerkleidet Euch damit und wartet irgendwo auf dem Berg im Norden auf diesen kleinen Knatzel Krungko. Wenn er aus seinem Versteck kommt, brecht ihm die Knochen!", sourceObjective = "Benutzt den alten Schafspelz irgendwo auf der Himmelsweite oder in Kunzen und tötet dann Krungko.", completion = "Danke, {name}. Das bringt mein Schäfchen zwar nicht zurück, aber wenigstens werde ich nun keine weiteren Schafe verlieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[31342] = { id = 31342, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Weg zum Respekt liegt in der Gewalt", description = "Ihr habt Euch im Kampf bewiesen.\n\nWenn Ihr uns auch weiterhin unterstützen wollt, hätte ich noch eine Bitte an Euch.\n\nDas Sha der Gewalt erwartet Euch in den versiegelten Kammern. Vernichtet es, wenn Ihr Euch meinen Respekt verdienen wollt.", sourceObjective = "Tötet das Sha der Gewalt.", completion = "Ihr habt das Sha der Gewalt besiegt und das Kloster gerettet - damit habt Ihr Euch meinen Respekt verdient.\n\nVielleicht haben wir Eure Art falsch eingeschätzt, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[31354] = { id = 31354, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mazus Freigiebigkeit", sourceObjective = "Sprecht mit Meisterangler Ju Lien in Tropfs Wagnis.", completion = "Hallo!\n\nAch, mir geht es gut. Ich habe nach einem Besuch im \"Abfalleimer\" Nächte erlebt, die schlimmer waren.\n\nJetzt seht Euch doch einmal dieses Ding an. Ich sah es aus dem Meeresboden ragen, als ich dort unten war - Jiao hat es wohl freigesetzt, als er um sich geschlagen hat.\n\nIch bin mir nicht ganz sicher, was ich damit anstellen soll, es sieht aber wertvoll aus. Ihr habt uns mehr oder weniger gerettet, deshalb glaube ich, dass wir Euch diesen Fang schulden.", sourceObjectiveStatus = "unverified-source-field" }
quests[31355] = { id = 31355, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wiederherstellung der Reinheit", description = "{class}, werdet Ihr uns helfen?\n\nDie Reinheit des Tempels ist in Gefahr. Just in diesem Moment kämpfen die drei Meister gegen ihre Zweifel an.\n\nBitte, ich flehe Euch an... helft dem weisen Mari, Liu Flammenherz und Lehrensucher Steinschritt in ihrem Kampf gegen das Sha.", sourceObjective = "Helft dem weisen Mari, Liu Flammenherz und Lehrensucher Steinschritt mit ihren Sha-Problemen.", completion = "Das Schicksal von Priesterin Flammenherz und dem weisen Mari stimmen mich zwar traurig, dennoch habt Ihr meinen aufrichtigen Dank.", sourceObjectiveStatus = "unverified-source-field" }
quests[31356] = { id = 31356, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tiefe Zweifel, tiefe Weisheit", description = "Ein altes Sprichwort der Pandaren sagt: \"Aus großen Zweifeln folgt große Weisheit.\"\n\nDas Sha des Zweifels hat sich im Tempel im Jadeherz eingenistet. Es muss vernichtet werden.\n\nIch möchte behaupten, dass Ihr bald sehr viel weiser sein werdet, {class}.", sourceObjective = "Tötet das Sha des Zweifels.", progress = "Das Sha des Zweifels muss vernichtet werden, {name}, oder wir sind alle verloren.", completion = "Ich habe nie an Euch gezweifelt. Komischerweise wirkt Ihr kein bisschen weiser.\n\n<Der Meister zwinkert mit dem Auge.>", sourceObjectiveStatus = "unverified-source-field" }
quests[31357] = { id = 31357, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Relikte der Vier Könige", description = "Die Mogu sind von Neuem erwacht und stellen eine Bedrohung für ganz Pandaria dar. Und sie stehen kurz davor, noch gefährlicher zu werden.\n\nEs gibt vier legendäre Großkönige der Mogu: Zian des endlosen Schattens, Meng der Irre, Qiang der Gnadenlose und Subetai der Schnelle. Vier Artefakte dieser Könige werden unter uns im Gewölbe der Vergangenen Könige unter Verschluss gehalten.\n\nIhr müsst diese Relikte beschaffen, bevor die Mogu sie entdecken und unaufhaltsam werden.", sourceObjective = "Beschafft die Laterne des Zaubererkönigs, die Waage von König Meng dem Irren, Qiangs \"Die Wissenschaft des Krieges\" und den Bogen von Subetai dem Schnellen.", progress = "Wir müssen die Laterne, die Waage, die Schriftrolle und den Bogen sicherstellen, bevor Xin und seine Klans sie entdecken.", completion = "Ich werde ein besseres Versteck für die vier Relikte finden.\n\nPandaria steht in Eurer Schuld, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[31359] = { id = 31359, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Kunchong-Flüsterer", description = "Um eine richtige Verbindung mit Kovok einzugehen, müsst Ihr ihn geistig und körperlich fordern. Respektiert seine Stärke und Intelligenz; nur dann wird er zulassen, dass Ihr ihn ernsthaft ausbildet.\n\nDie Schlickschuppen dienen möglicherweise als angemessene Prüfung seiner Fähigkeiten, und wenn Ihr dabei seid, ist er nicht in Gefahr.\n\nAußerdem können wir damit ihre Reihen im Salzigen Schlick lichten.", sourceObjective = "Tötet das Orakel Zisch'et und 10 Angehörige des Stammes der Schlickschuppen.", completion = "Euer Fortschritt ist höchst beeindruckend, Erwecker. Kovoks Training schreitet gut voran und er scheint Euch zu mögen.\n\nIhr seid zweifelsfrei die beste Wahl, um mir bei seiner Erziehung zu helfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[31360] = { id = 31360, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine neue Lektion für den Meister", description = "Ein neuer König der Mogu ist an der Macht: Xin der Waffenmeister.\n\nHat die Klans der Mogu eigenhändig unterworfen... Deren neue Anführer buhlen nun um seine Gunst.\n\nIch weiß von niemandem, der ihm im Kampf das Wasser reichen könnte. Unterschätzt Xin nicht, {name}.\n\nUnser Schicksal liegt in Euren Händen.", sourceObjective = "Tötet Xin den Waffenmeister.", completion = "Eine wahrlich legendäre Schlacht.\n\nIch bin froh, dass Ihr auf unserer Seite seid, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[31362] = { id = 31362, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das letzte Puzzleteil", description = "Ich muss sagen, {name}, trotz der Scharmützel mit den Ho-zen habe ich die Jinyu noch nie so militant erlebt.\n\nDas beunruhigt mich. Allerdings müssen wir das zu einem anderen Zeitpunkt besprechen. Ich bin hier, um Euch um Eure Unterstützung zu bitten.\n\nDas uralte Fresko, dort, wo wir uns zuletzt unterhielten, ist fast enthüllt. Ich bin mir sicher, dass es uralte Weisheit enthält - Weisheit, von der der Kaiser wollte, dass wir sie nicht vergessen.\n\nDurch Meditation allein kann ich ihre Bedeutung vielleicht nicht rechtzeitig enthüllen. Bitte, bringt dieses Erbstück zum Schrein meiner Ahnen. Mit ihrer Hilfe werden wir dieses Rätsel lösen können.", sourceObjective = "Benutzt Chos Erbstück bei Chos Familienschrein beim Schlangenblick.\n\nUm dorthin zu kommen, sprecht mit Mishi.", completion = "<Lehrensucher Cho schüttelt sich unwillkürlich.>\n\nDie Legenden… sie sind wahr!", sourceObjectiveStatus = "unverified-source-field" }
quests[31363] = { id = 31363, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gebt das Signal", description = "Wir brauchen Verstärkung! Jemand muss sich durchkämpfen und die Signalflamme entfachen.\n\nEs hängt alles von Euch ab, {class}. Fühlt Euch jetzt bloß nicht unter Druck gesetzt oder so.", sourceObjective = "Entfacht die Signalflamme.", completion = "Hervorragend, {name}. Ihr hättet es von der Zeit her nicht besser machen können!", sourceObjectiveStatus = "unverified-source-field" }
quests[31364] = { id = 31364, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Was für ein Brocken!", description = "Die Mantis verfügen über etwas, das sie Raigonn nennen. Es ist ein riesiges Insekt, mit dem sie die Tore der Mauer einstoßen!\n\nLasst uns sicherstellen, dass dieses Ding nicht ins Tal gelangt!", sourceObjective = "Tötet Raigonn.", completion = "Hätte ich es nicht mit eigenen Augen gesehen, ich hätte es wohl nicht geglaubt.\n\nGut gemacht, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[31365] = { id = 31365, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Irgendwo da drinnen", description = "Ich habe ein Dutzend meiner besten Männer vorausgeschickt, um die Mantisbelagerung zu infiltrieren.\n\nKeiner von ihnen ist bisher zurückgekehrt.\n\nDa Ihr die Mantis direkt angreifen werdet, bietet sich Euch die Chance, alle zu befreien, die das Pech hatten, in Gefangenschaft zu geraten.\n\nWerdet Ihr das für uns tun?", sourceObjective = "Rettet 12 gefangene Shado-Pan.", progress = "Meine Männer werden irgendwo im Bereich der Mantisbelagerung festgehalten.", completion = "Ich sage dreizehnmal danke - zwölfmal für jene, die Ihr gerettet habt, und einmal für mich selbst.\n\nUnd hier ist noch etwas, das ich Euch als Zeichen der Dankbarkeit überreichen möchte.", sourceObjectiveStatus = "unverified-source-field" }
quests[31366] = { id = 31366, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schaltet den Schwadronsführer aus", description = "Die Mantis belagern den Niuzaotempel.\n\nSchwadronsführer Ner'onok und seine Einheit arbeiten in diesem Augenblick daran, die letzte Kluft zu überbrücken.\n\nIhr müsst ihn und seine Leute aufhalten, bevor sie die Brücke wieder aufbauen.", sourceObjective = "Tötet Schwadronsführer Ner'onok.", completion = "Der Schwadronsführer ist tot, die Belagerung zerschlagen.\n\nIhr habt den Tempel gerettet, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[31367] = { id = 31367, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Lehrensucher", description = "Ihr wollt also mehr über dieses Land erfahren?\n\nSehr gut! Dann solltet Ihr mit Lehrensucher Cho im Heim des Wissens sprechen.\n\nIhr findet ihn in dem Raum oberhalb des Eingangs zum Mogu'shanpalast. Sprecht mit Mishi, um dorthin zu gelangen.", sourceObjective = "Sprecht mit Lehrensucher Cho im Heim des Wissens im Tal der Ewigen Blüten.", completion = "Ja, ich kann Euch am Gesicht ansehen, dass Ihr ein Interesse an der Geschichte habt. Dann seid Ihr hier am richtigen Ort.", sourceObjectiveStatus = "unverified-source-field" }
quests[31368] = { id = 31368, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Lehrensucher", description = "Ihr wollt also mehr über dieses Land erfahren?\n\nSehr gut! Dann solltet Ihr mit Lehrensucher Cho im Heim des Wissens sprechen.\n\nIhr findet ihn in dem Raum oberhalb des Eingangs zum Mogu'shanpalast. Sprecht mit Mishi, um dorthin zu gelangen.", sourceObjective = "Sprecht mit Lehrensucher Cho im Heim des Wissens im Tal der Ewigen Blüten.", completion = "Ja, ich kann Euch am Gesicht ansehen, dass Ihr ein Interesse an der Geschichte habt. Dann seid Ihr hier am richtigen Ort.", sourceObjectiveStatus = "unverified-source-field" }
quests[31369] = { id = 31369, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Angler", description = "Wenn Ihr all die Geheimnisse des tiefen Ozeans erkunden und ein paar richtig große Fische fangen wollt, solltet Ihr mit Haito an der Anlegestelle der Angler in der Krasarangwildnis sprechen.\n\nEr wird Euch sicher gern ein oder zwei Dinge über die Angelei erzählen!", sourceObjective = "Sprecht mit dem Angler Haito an der Anlegestelle der Angler in der Krasarangwildnis.", completion = "Seid Ihr bereit für GROSSE Fische?", sourceObjectiveStatus = "unverified-source-field" }
quests[31370] = { id = 31370, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Angler", description = "Wenn Ihr all die Geheimnisse des tiefen Ozeans erkunden und ein paar richtig große Fische fangen wollt, solltet Ihr mit Haito an der Anlegestelle der Angler in der Krasarangwildnis sprechen.\n\nEr wird Euch sicher gern ein oder zwei Dinge über die Angelei erzählen!", sourceObjective = "Sprecht mit dem Angler Haito an der Anlegestelle der Angler in der Krasarangwildnis.", completion = "Seid Ihr bereit für GROSSE Fische?", sourceObjectiveStatus = "unverified-source-field" }
quests[31372] = { id = 31372, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Ackerbauern", description = "Die Ackerbauern gehen ihrem Beruf in Halbhügel im Tal der Vier Winde nach.\n\nWenn Ihr Interesse an ihrer Arbeit habt, solltet Ihr vielleicht mit Bauer Yoon sprechen. Er ist noch neu im Ort.\n\nIch wette, er kann etwas Hilfe gebrauchen.", sourceObjective = "Sprecht mit Bauer Yoon auf dem Gehöft Sonnensang im Tal der Vier Winde.", completion = "Ihr kommt genau zur rechten Zeit!", sourceObjectiveStatus = "unverified-source-field" }
quests[31373] = { id = 31373, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Orden der Wolkenschlange", description = "Der Orden der Wolkenschlange ist immer auf der Suche nach Reittalenten.\n\nWenn Ihr Euch uns anschließen wollt, solltet Ihr mit Ausbilder Himmelsdorn im Arboretum im Jadewald sprechen.\n\nIch wünsche Euch viel Glück, {race}.", sourceObjective = "Sprecht mit Ausbilder Himmelsdorn im Arboretum im Jadewald.", completion = "Ah, Ihr möchtet Euch unserem Orden anschließen?", sourceObjectiveStatus = "unverified-source-field" }
quests[31374] = { id = 31374, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Ackerbauern", description = "Die Ackerbauern gehen ihrem Beruf in Halbhügel im Tal der Vier Winde nach.\n\nWenn Ihr Interesse an ihrer Arbeit habt, solltet Ihr vielleicht mit Bauer Yoon sprechen. Er ist noch neu im Ort.\n\nIch wette, er kann etwas Hilfe gebrauchen.", sourceObjective = "Sprecht mit Bauer Yoon auf dem Gehöft Sonnensang im Tal der Vier Winde.", sourceObjectiveStatus = "unverified-source-field" }
quests[31375] = { id = 31375, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Orden der Wolkenschlange", description = "Der Orden der Wolkenschlange ist immer auf der Suche nach Reittalenten.\n\nWenn Ihr Euch uns anschließen wollt, solltet Ihr mit Ausbilder Himmelsdorn im Arboretum im Jadewald sprechen.\n\nIch wünsche Euch viel Glück, {race}.", sourceObjective = "Sprecht mit Ausbilder Himmelsdorn im Arboretum im Jadewald.", completion = "Ah, Ihr möchtet Euch unserem Orden anschließen?", sourceObjectiveStatus = "unverified-source-field" }
quests[31376] = { id = 31376, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angriff auf den Tempel der Jadeschlange", description = "Der Tempel der Jadeschlange wird in Dunkelheit gehüllt und Yu'lons Priester haben uns um Hilfe gebeten.\n\nNoch können sie das Sha in Schach halten, aber nicht mehr lange.\n\nVielleicht gelingt es Euch ja, den Feind zu überwinden, {class}.", sourceObjective = "Sprecht mit dem Ältestenweisen Tai-Feng auf dem Tempelgelände der Jadeschlange im Jadewald.", completion = "Ihr kommt gerade rechtzeitig.", sourceObjectiveStatus = "unverified-source-field" }
quests[31377] = { id = 31377, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angriff auf den Tempel der Jadeschlange", description = "Der Tempel der Jadeschlange wird in Dunkelheit gehüllt und Yu'lons Priester haben uns um Hilfe gebeten.\n\nNoch können sie das Sha in Schach halten, aber nicht mehr lange.\n\nVielleicht gelingt es Euch ja, den Feind zu überwinden, {class}.", sourceObjective = "Sprecht mit dem Ältestenweisen Tai-Feng auf dem Tempelgelände der Jadeschlange im Jadewald.", completion = "Ihr kommt gerade rechtzeitig.", sourceObjectiveStatus = "unverified-source-field" }
quests[31378] = { id = 31378, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Herausforderung am Tempel des Roten Kranichs", description = "Der Tempel des Roten Kranichs ist nach dem Auftauchen des Sha immer noch in Aufruhr. Erst vor Kurzem konnten sie beginnen, die Truppen zu sammeln und die Übungen für die Krieger wieder aufzunehmen.\n\nWenn Ihr dem Tempel helfen möchtet, dann sprecht mit Thelonius an Chi-Jis Wiege.", sourceObjective = "Sprecht mit Thelonius an Chi-Jis Wiege in der Krasarangwildnis.", completion = "Ich heiße Euch willkommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[31379] = { id = 31379, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Herausforderung am Tempel des Roten Kranichs", description = "Der Tempel des Roten Kranichs ist nach dem Auftauchen des Sha immer noch in Aufruhr. Erst vor Kurzem konnten sie beginnen, die Truppen zu sammeln und die Übungen für die Krieger wieder aufzunehmen.\n\nWenn Ihr dem Tempel helfen möchtet, dann sprecht mit Thelonius an Chi-Jis Wiege.", sourceObjective = "Sprecht mit Thelonius an Chi-Jis Wiege in der Krasarangwildnis.", completion = "Ich heiße Euch willkommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[31380] = { id = 31380, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Herausforderung am Tempel des Weißen Tigers", description = "Xuen, der große Himmlische des Nordes, ist auf der Suche nach den größten Kämpfern des Landes.\n\nHeute wird er seine Herausforderungen am Kun-Lai-Gipfel abhalten.\n\nWenn Ihr Euch mit den stärksten Kämpfern aus ganz Pandaria messen wollt, dann sucht ihn auf und betretet den Ring der Herausforderer!", sourceObjective = "Sprecht mit Xuen am Tempel des Weißen Tigers am Kun-Lai-Gipfel.", completion = "Ihr möchtet also Eure Fähigkeiten auf die Probe stellen? Sehr gut, {race}.", sourceObjectiveStatus = "unverified-source-field" }
quests[31381] = { id = 31381, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Herausforderung am Tempel des Weißen Tigers", description = "Xuen, der große Himmlische des Nordes, ist auf der Suche nach den größten Kämpfern des Landes.\n\nHeute wird er seine Herausforderungen am Kun-Lai-Gipfel abhalten.\n\nWenn Ihr Euch mit den stärksten Kämpfern aus ganz Pandaria messen wollt, dann sucht ihn auf und betretet den Ring der Herausforderer!", sourceObjective = "Sprecht mit Xuen am Tempel des Weißen Tigers am Kun-Lai-Gipfel.", completion = "Ihr möchtet also Eure Fähigkeiten auf die Probe stellen? Sehr gut, {race}.", sourceObjectiveStatus = "unverified-source-field" }
quests[31382] = { id = 31382, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Verteidigung des Niuzaotempels", description = "Der Niuzaotempel im äußersten Westen, wird von den Mantis angegriffen.\n\nBis jetzt konnte der Große Himmlische sie aufhalten, aber auf sich allein gestellt kann selbst er nicht ewig durchhalten.\n\nIhr müsst den Verteidigern helfen, {class}. Der Tempel darf nicht fallen!", sourceObjective = "Sprecht mit Ogo dem Ältesten im Niuzaotempel in der Tonlongsteppe.", completion = "Ich grüße Euch. Wir können Eure Hilfe wirklich gebrauchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[31383] = { id = 31383, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Verteidigung des Niuzaotempels", description = "Der Niuzaotempel im äußersten Westen, wird von den Mantis angegriffen.\n\nBis jetzt konnte der Große Himmlische sie aufhalten, aber auf sich allein gestellt kann selbst er nicht ewig durchhalten.\n\nIhr müsst den Verteidigern helfen, {class}. Der Tempel darf nicht fallen!", sourceObjective = "Sprecht mit Ogo dem Ältesten im Niuzaotempel in der Tonlongsteppe.", completion = "Ich grüße Euch. Wir können Eure Hilfe wirklich gebrauchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[31384] = { id = 31384, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Goldene Lotus", description = "Der Goldene Lotus bewacht das Tal seit Jahrhunderten. Er hat für seine Sicherheit gesorgt und es vor Schaden bewahrt.\n\nDie jüngsten Ereignisse haben fürchterliche Schrecken über unser Tal gebracht, aber die Verbündeten des Goldenen Lotus halten immer noch gegen sie aus und versuchen, den Frieden wiederherzustellen.\n\nWenn Ihr helfen möchtet, stoßt Ihr am besten bei der Garnison der Untergehenden Sonne zu ihnen.", sourceObjective = "Sprecht mit Anji Herbstlicht in der Garnison der Untergehenden Sonne im Tal der Ewigen Blüten.", completion = "Seid gegrüßt, {race}. Ihr scheint dem Aussehen nach über einige Fähigkeiten zu verfügen. Gut jemand so fähiges wie Euch, {class}, auf unserer Seite zu wissen.", sourceObjectiveStatus = "unverified-source-field" }
quests[31385] = { id = 31385, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Goldene Lotus", description = "Der Goldene Lotus bewacht das Tal seit Jahrhunderten. Er hat für seine Sicherheit gesorgt und es vor Schaden bewahrt.\n\nDie jüngsten Ereignisse haben fürchterliche Schrecken über unser Tal gebracht, aber die Verbündeten des Goldenen Lotus halten immer noch gegen sie aus und versuchen, den Frieden wiederherzustellen.\n\nWenn Ihr helfen möchtet, stoßt Ihr am besten bei der Garnison der Untergehenden Sonne zu ihnen.", sourceObjective = "Sprecht mit Anji Herbstlicht in der Garnison der Untergehenden Sonne im Tal der Ewigen Blüten.", completion = "Seid gegrüßt, {race}. Ihr scheint dem Aussehen nach über einige Fähigkeiten zu verfügen. Gut jemand so fähiges wie Euch, {class}, auf unserer Seite zu wissen.", sourceObjectiveStatus = "unverified-source-field" }
quests[31386] = { id = 31386, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Shado-Pan-Offensive", description = "Wir Shado-Pan haben unsere Truppen zum ersten Mal seit vielen, vielen Jahren wieder zusammengezogen.\n\nDas Sha des Hasses ist aus seinem Gefängnis jenseits des Schlangenrückens entkommen und es ist unsere heilige Pflicht, es wieder gefangen zu nehmen.\n\nUnsere Krieger sind zwar sehr fähig, aber leider viel zu wenige. Eure Hilfe werden wir also nicht ablehnen, {class}.\n\nWenn Ihr Euch der Offensive anschließen wollt, sprecht mit Taran Zhu in der Tonlongsteppe.", sourceObjective = "Sprecht mit Taran Zhu am Außenposten Longying in der Tonlongsteppe.", completion = "Ich grüße Euch, {race}.", sourceObjectiveStatus = "unverified-source-field" }
quests[31387] = { id = 31387, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Shado-Pan verstehen", description = "Die Shado-Pan gehören zu den ältesten Beschützern Pandarias.\n\nÜber viele Jahre hinweg werden wir in unserem schneebedeckten Kloster hoch auf dem Kun-Lai-Gipfel ausgebildet. Dabei perfektionieren wir die Geheimnisse der Kampfkunst, die uns von unseren Ahnen weitergereicht wurden.\n\nWir mögen nur Wenige sein, doch ein einzelner Shado-Pan kann tödlicher sein als hundert gut ausgebildete Soldaten.\n\nSich dem Orden der Shado-Pan anzuschließen ist ein langwieriges und mühsames Unterfangen voller Entbehrungen. Solltet Ihr diesen Pfad beschreiten wollen, müsst Ihr Euch erst als würdig erweisen.\n\nEs gibt hier dringende Aufgaben zu erledigen. Helft dem Goldenen Lotus bei der Verteidigung des Tals.", sourceObjective = "Erlangt beim Goldenen Lotus einen respektvollen Ruf.", sourceObjectiveStatus = "unverified-source-field" }
quests[31388] = { id = 31388, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Shado-Pan-Offensive", description = "Wir Shado-Pan haben unsere Truppen zum ersten Mal seit vielen, vielen Jahren wieder zusammengezogen.\n\nDas Sha des Hasses ist aus seinem Gefängnis jenseits des Schlangenrückens entkommen und es ist unsere heilige Pflicht, es wieder gefangen zu nehmen.\n\nUnsere Krieger sind zwar sehr fähig, aber leider viel zu wenige. Eure Hilfe werden wir also nicht ablehnen, {class}.\n\nWenn Ihr Euch der Offensive anschließen wollt, sprecht mit Taran Zhu in der Tonlongsteppe.", sourceObjective = "Sprecht mit Taran Zhu am Außenposten Longying in der Tonlongsteppe.", completion = "Ich grüße Euch, {race}.", sourceObjectiveStatus = "unverified-source-field" }
quests[31389] = { id = 31389, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Shado-Pan verstehen", description = "Die Shado-Pan gehören zu den ältesten Beschützern Pandarias.\n\nÜber viele Jahre hinweg werden wir in unserem schneebedeckten Kloster hoch auf dem Kun-Lai-Gipfel ausgebildet. Dabei perfektionieren wir die Geheimnisse der Kampfkunst, die uns von unseren Ahnen weitergereicht wurden.\n\nWir mögen nur Wenige sein, doch ein einzelner Shado-Pan kann tödlicher sein als hundert gut ausgebildete Soldaten.\n\nSich dem Orden der Shado-Pan anzuschließen ist ein langwieriges und mühsames Unterfangen voller Entbehrungen. Solltet Ihr diesen Pfad beschreiten wollen, müsst Ihr Euch erst als würdig erweisen.\n\nEs gibt hier dringende Aufgaben zu erledigen. Helft dem Goldenen Lotus bei der Verteidigung des Tals.", sourceObjective = "Erlangt beim Goldenen Lotus einen respektvollen Ruf.", sourceObjectiveStatus = "unverified-source-field" }
quests[31390] = { id = 31390, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Klaxxi", description = "Die Existenz der Klaxxi ist nur eine unbestätigte Legende. Sie sollen weit jenseits der Mauer in der Schreckensöde leben.\n\nDieses Gebiet haben nur wenige betreten. Und noch weniger sind je wieder von dort zurückgekehrt, um ihre Eindrücke zu schildern.\n\nWenn Ihr also unbedingt diese... Klaxxi... finden wollt, es gibt da eine kleine Gruppe Shado-Pan, die die Mauer im Südwesten beschützt. Sie können Euch vielleicht mehr erzählen.", sourceObjective = "Sprecht mit Bogenmeisterin Li am Tor der Untergehenden Sonne zwischen dem Tal der Ewigen Blüten und der Schreckensöde.", completion = "Die Schreckensöde ist ein gefährlicher Ort.", sourceObjectiveStatus = "unverified-source-field" }
quests[31391] = { id = 31391, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Klaxxi", description = "Die Existenz der Klaxxi ist nur eine unbestätigte Legende. Sie sollen weit jenseits der Mauer in der Schreckensöde leben.\n\nDieses Gebiet haben nur wenige betreten. Und noch weniger sind je wieder von dort zurückgekehrt, um ihre Eindrücke zu schildern.\n\nWenn Ihr also unbedingt diese... Klaxxi... finden wollt, es gibt da eine kleine Gruppe Shado-Pan, die die Mauer im Südwesten beschützt. Sie können Euch vielleicht mehr erzählen.", sourceObjective = "Sprecht mit Bogenmeisterin Li am Tor der Untergehenden Sonne zwischen dem Tal der Ewigen Blüten und der Schreckensöde.", completion = "Die Schreckensöde ist ein gefährlicher Ort.", sourceObjectiveStatus = "unverified-source-field" }
quests[31392] = { id = 31392, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tempel des Weißen Tigers", description = "Habt Ihr die Neuigkeiten vernommen, <Reisender/Reisende>? Einer unserer heiligsten Orte wurde angegriffen, das Tal der Ewigen Blüten!\n\nIn diesem Augenblick ist ein menschlicher Prinz im Tempel des Weißen Tigers, der dafür plädiert, dass Euch und den anderen Völkern von jenseits der Nebel Einlass gewährt wird.\n\nDer Tempel befindet sich im Nordosten des Kun-Lai. Vielleicht könnt Ihr den Weißen Tiger überzeugen, Euch hineinzulassen?\n\nIch kann nur hoffen, dass das Tal nicht vollständig zerstört wurde...", sourceObjective = "Sprecht mit Anduin Wrynn im Tempel des Weißen Tigers am Kun-Lai-Gipfel.", completion = "{class}, ich bin froh, dass Ihr hier seid! In den Überlieferungen der Pandaren gibt es einen legendären Ort, das Tal der Ewigen Blüten. Wenn man den Geschichten der Einheimischen Glauben schenken kann, handelt es sich um einen Ort mit großen heilerischen Kräften.\n\nAber der Kriegshäuptling der Horde hat dem Tal Unsagbares angetan.\n\nWir müssen dort einfach hinein!", sourceObjectiveStatus = "unverified-source-field" }
quests[31393] = { id = 31393, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tempel des Weißen Tigers", description = "Habt ihr die Neuigkeiten vernommen, <Reisender/Reisende>? Einer unserer heiligsten Orte wurde angegriffen, das Tal der Ewigen Blüten!\n\nIn diesem Augenblick ist ein menschlicher Prinz im Tempel des Weißen Tigers, der dafür plädiert, dass Euch und den anderen Völkern von jenseits der Nebel Einlass gewährt wird.\n\nDer Tempel befindet sich im Nordosten des Kun-Lai. Vielleicht könnt Ihr den Weißen Tiger überzeugen, Euch hineinzulassen?\n\nIch kann nur hoffen, dass das Tal nicht vollständig zerstört wurde...", sourceObjective = "Sprecht mit Dezco im Tempel des Weißen Tigers am Kun-Lai-Gipfel.", completion = "Hallo, {class}! Uns wurde eine Audienz beim Weißen Tiger gewährt. Das Tal der Ewigen Blüten wurde unlängst von unserem Kriegshäuptling verheert. Unser Anliegen ist es, dass Horde und Allianz zugleich der Zugang zum Tal gewährt wird, damit die Schäden repariert werden können.\n\nDas Tal ist ein heiliger Ort. Ich glaube, meine Frau Leza sah es in einer Vision – darum ist mein Volk nach Pandaria gekommen. Wir müssen es retten!\n\nMeint Ihr, man wird uns Zugang gewähren?", sourceObjectiveStatus = "unverified-source-field" }
quests[31394] = { id = 31394, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine himmlische Erfahrung", description = "Niemand darf das Tal ohne die Erlaubnis der Himmlischen Erhabenen betreten. Xuen der Weiße Tiger scheint mir Gehör schenken zu wollen.\n\nNach allem, was sich zugetragen hat, sträubt sich Taran Zhu von den Shado-Pan aber dagegen, die Allianz oder die Horde auch nur in die NÄHE des Tals zu lassen.\n\n<Anduin schüttelt den Kopf.>\n\nVielleicht könnt Ihr mir ja helfen, mein Anliegen vorzutragen. Sprecht in unserem Namen mit dem Weißen Tiger. Doch seid vorsichtig! Er könnte Euch eine Reihe von Prüfungen auferlegen...", sourceObjective = "Sprecht mit Xuen und schließt seine Prüfungen ab.", progress = "Seid Ihr mit den Aufgaben des Weißen Tigers fertig?", completion = "Ihr habt es geschafft, {name}!\n\nDer Weiße Tiger hat uns erlaubt, die Pandaren in das Tal der Ewigen Blüten zu begleiten. Wir können dort einen Außenposten der Allianz errichten, der als unsere Botschaft bei den Pandaren fungieren kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[31395] = { id = 31395, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine himmlische Erfahrung", description = "Das menschliche Kalb tritt für uns ein. Er ist sehr wortgewandt. Ich kann sehen, warum Baine Bluthuf den Prinzen so sehr schätzt.\n\nDennoch kann ich dieses Argument nicht gelten lassen. Ich bin nicht von Bedeutung, Ihr hingegen seid <ein Held/eine Heldin> der Horde. Vielleicht könntet Ihr ja zu unseren Gunsten vermitteln?\n\nSprecht mit dem Weißen Tiger und tretet für unsere Sache ein, {race}.\n\nSeid vorsichtig! Er könnte Euch eine Reihe von Prüfungen auferlegen...", sourceObjective = "Sprecht mit Xuen und besteht seine Prüfungen.", completion = "Ihr habt es geschafft, {name}!\n\nDer Weiße Tiger hat uns erlaubt, die Pandaren in das Tal der Ewigen Blüten zu begleiten.\n\nEin Held der Horde hat geschafft, woran der Prinz der Allianz gescheitert ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[31398] = { id = 31398, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auseinanderfallen", description = "Warum haben die Saurok Bern? Und noch viel wichtiger: Warum bewacht das Orakel Zish'et ihn so eifersüchtig?\n\nDass er aus dem schwer bewachten Zan'vess stammt, ist unwahrscheinlich - woher kommt er also?\n\nVielleicht wissen die Klaxxi, was wir davon halten sollen.", sourceObjective = "Bringt Kaz'tik dem Manipulator den leuchtenden Bern zurück.", progress = "Wo habt Ihr das gefunden?", completion = "Es war klug von Euch, uns das zu bringen. Das ist ein Stück Bern, das einen anderen Getreuen umhüllt hat.\n\nDer Schaden deutet darauf hin, dass der Getreue in Schwierigkeiten stecken könnte.\n\nIch werde mit dem Rat sprechen, um eine Entscheidung zu treffen, was als Nächstes geschehen soll.", sourceObjectiveStatus = "unverified-source-field" }
quests[31439] = { id = 31439, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verlorenes Signal", description = "Jemand scheint sich am Signalfeuer in der Bernscheinkuhle zu schaffen gemacht zu haben. Kurz bevor es ausfiel, empfingen die Klaxxi'va ein Signal von einem anderen Getreuen in der Nähe.\n\nSie glauben, er versteckt sich in diesem elenden kleinen Sumpf, dem Dämmerwurzmoor.\n\nIch werde Euch im Moor treffen, um ein Behelfssignal aufzustellen, bis ich die Bernscheinkuhle wieder zum Laufen bringe.\n\nIhr werdet den Getreuen erwecken und dann werdet Ihr mir helfen.", sourceObjective = "Erweckt den Getreuen im Dämmerwurzmoor.", completion = "Wie es scheint, fängt meine Arbeit gleich an. Ihr seid an einen gefährlichen Ort gekommen, Erwecker.", sourceObjectiveStatus = "unverified-source-field" }
quests[31440] = { id = 31440, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die vier Folianten", description = "In Scholomance gibt es vier große Folianten mit mächtigem nekromantischem Wissen: \"Im Schatten des Lichts\", \"Kel'Thuzads tiefgründiges Wissen\", \"Verbotene Riten und andere nekromantische Rituale\" und \"Der dunkle Zauberfoliant\".\n\nWährend wir uns unseren Weg durch diesen verfluchten Ort bahnen, müsst Ihr jedes dieser Bücher finden und vernichten. Wir müssen verhindern, dass sich auch nur ein weiterer Dummkopf ihre teuflischen Geheimnisse zu eigen macht.", sourceObjective = "Vernichtet die vier Folianten: \"Im Schatten des Lichts\", \"Kel'Thuzads tiefgründiges Wissen\", \"Verbotene Riten und andere nekromantische Rituale\" und \"Der dunkle Zauberfoliant\".", progress = "Die Geheimnisse der vier Folianten haben diesen Ort und alle, die mit ihm in Verbindung stehen, zu ewigem Leiden verdammt.\n\nSie müssen zerstört werden!", completion = "Danke, {name}.\n\nDa die Folianten nun zerstört sind, kann ich meine ewige Ruhe in dem Wissen antreten, dass diese Bücher niemals wieder einer lebenden Seele schaden werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[31441] = { id = 31441, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Korruption auf allen Ebenen", description = "Heute lernt Ihr, dass man zu Kriegszeiten niemandem vertrauen kann, <Erwecker/Erweckerin>. Selbst diejenigen, die den Klaxxi am nächsten stehen, sind anfällig für Korruption.\n\nWer weiß, seit wann dieser Verräter schon verdorben ist. Er muss vernichtet werden!\n\nIhr seht verwirrt aus. Seht Ihr den Verräter in unseren Reihen denn nicht? Erlaubt mir, Euren Blick zu korrigieren.", sourceObjective = "Bezwingt den Verräter im Dämmerwurzmoor.", completion = "Davon werdet Ihr mehr zu sehen bekommen. Der Krieg ist niemals ein hübscher Anblick.\n\nDie Verderbtheit der Kaiserin reicht weit und ist nur schwer zu entdecken.\n\nEs gibt viel zu tun. Wir müssen anfangen, den Schaden, den Kor'ik angerichtet hat, wiedergutzumachen.", sourceObjectiveStatus = "unverified-source-field" }
quests[31442] = { id = 31442, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die vier Folianten", description = "In Scholomance gibt es vier große Folianten mit mächtigem nekromantischem Wissen: \"Im Schatten des Lichts\", \"Kel'Thuzads tiefgründiges Wissen\", \"Verbotene Riten und andere nekromantische Rituale\" und \"Der dunkle Zauberfoliant\".\n\nWährend wir uns unseren Weg durch diesen verfluchten Ort bahnen, müsst Ihr jedes dieser Bücher finden und vernichten. Wir müssen verhindern, dass sich auch nur ein weiterer Dummkopf ihre teuflischen Geheimnisse zu eigen macht.", sourceObjective = "Vernichtet die vier Folianten: \"Im Schatten des Lichts\", \"Kel'Thuzads tiefgründiges Wissen\", \"Verbotene Riten und andere nekromantische Rituale\" und \"Der dunkle Zauberfoliant\".", progress = "Die Geheimnisse der vier Folianten haben diesen Ort und alle, die mit ihm in Verbindung stehen, zu ewigem Leiden verdammt.\n\nSie müssen zerstört werden!", completion = "Danke, {name}.\n\nDa die Folianten nun zerstört sind, kann ich meine ewige Ruhe in dem Wissen antreten, dass diese Bücher niemals wieder einer lebenden Seele schaden werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[31443] = { id = 31443, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fliegender Tigergurami", description = "Ihr habt einen einzigartigen Fisch gefangen... mit Flügeln. Vielleicht solltet Ihr Nat Pagle bei der Anlegestelle der Angler nach seiner Expertenmeinung fragen.", sourceObjective = "Bringt den fliegenden Tigergurami zu Nat Pagle an der Anlegestelle der Angler.", progress = "Fliegende Fische?", completion = "Ist das ein fliegender Tigergurami?\n\nBei diesem kleinen Fisch handelt es sich um eine seltene Mutation von Tigergurami, die des Fliegens mächtig sind und daher im Süßwasser von Pandaria gefangen werden können.\n\nDen hiesigen Legenden zufolge soll der Person, die diesen Fisch verzehrt, das Glück hold sein. Und die örtliche Tradition gebietet, dass nur der Adel ihn verzehren darf. Wer diese \"Tradition\" verletzt, unterschreibt damit sein eigenes Todesurteil.\n\nIch werde folglich dafür sorgen, dass der Fisch den richtigen Abnehmer findet.", sourceObjectiveStatus = "unverified-source-field" }
quests[31444] = { id = 31444, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stachelfischalpha", description = "Ihr habt etwas ganz Besonderes gefangen... und es sieht ziemlich aggressiv aus.\n\nVielleicht weiß Nat Pagle an der Anlegestelle der Angler mehr darüber?", sourceObjective = "Bringt den Stachelfischalpha zu Nat Pagle an der Anlegestelle der Angler.", progress = "Merkwürdige Fische?", completion = "Das ist doch nicht etwa das, wofür ich es halte, oder? Oh Mann, ein Stachelfischalpha, eines der tödlichsten Raubtiere Pandarias.\n\nStachelfische sind verformte Monstrositäten, die durch die Gegenwart eines Sha entstanden. Die größten Exemplare sind einfach furchterregend. Die Alphatiere verschlingen oft die anderen Stachelfische, obwohl an ihnen absolut nichts Essbares ist.\n\nZu unser beider Glück sind sie für Alchemisten hochinteressant.", sourceObjectiveStatus = "unverified-source-field" }
quests[31445] = { id = 31445, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "zzOld", description = "Wenn Ihr all die Geheimnisse der Tiefsee erforschen und einige große Fische fangen wollt, sprecht mit meinem Bruder Haito an der Anglegestelle der Angler in der Krasarangwildnis.\n\nIch bin mir sicher, dass er Euch gern die eine oder andere Sache über die Angelkunst beibringt.", sourceObjective = "Sprecht mit Angler Haito an der Anlegestelle der Angler in der Krasarangwildnis.", sourceObjectiveStatus = "unverified-source-field" }
quests[31446] = { id = 31446, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fintenfisch", description = "Ihr wisst nicht genau wie, aber Ihr habt einen außergewöhnlichen Kopffüßler gefangen. Nat Pagle an der Anlegestelle der Angler dürfte sich sehr dafür interessieren.", sourceObjective = "Bringt den Fintenfisch zu Nat Pagle an der Anlegestelle der Angler.", progress = "Sich tarnende Tintenfische?", completion = "Ist das ein Fintenfisch? Einer meiner Kumpels hat vor einigen Jahren mal einen vor der Küste von Zandalar gefangen. Hätte es fast nicht lebend zurück geschafft. Lästige Trolle dort, aber schöne Gegend zum Angeln!\n\nJedenfalls sind die Tierchen nicht so selten, wie Ihr vielleicht meint. Sie tarnen sich, um sich unter Steinen und Pflanzen zu verstecken. Nur die besten Angler können sich Chancen ausrechnen, diesen scheuen, aber unglaublich gut schmeckenden Leckerbissen zu fangen.", sourceObjectiveStatus = "unverified-source-field" }
quests[31447] = { id = 31447, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dem Leiden ein Ende", sourceObjective = "Tötet Dunkelmeister Gandling.", completion = "Erblickt meine wahre Gestalt.\n\nIch stehe tief in Eurer Schuld, werde sie aber niemals begleichen können. Doch ich danke Euch, dass Ihr meine Familie von diesem Fluch befreit habt.\n\nKel'Thuzad, der Lichkönig, und nun auch Dunkelmeister Gandling - sie alle sind tot.\n\nVielleicht finde ja nun auch ich eine Art von Frieden.", sourceObjectiveStatus = "unverified-source-field" }
quests[31448] = { id = 31448, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dem Leiden ein Ende", sourceObjective = "Tötet Dunkelmeister Gandling.", completion = "Erblickt meine wahre Gestalt.\n\nIch stehe tief in Eurer Schuld, werde sie aber niemals begleichen können. Doch ich danke Euch, dass Ihr meine Familie von diesem Fluch befreit habt.\n\nKel'Thuzad, der Lichkönig, und nun auch Dunkelmeister Gandling - sie alle sind tot.\n\nVielleicht finde ja nun auch ich eine Art von Frieden.", sourceObjectiveStatus = "unverified-source-field" }
quests[31450] = { id = 31450, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein neues Schicksal", description = "Diese neuen Verbündeten haben uns Aufschluss über eine große und wichtige Wahrheit gegeben: Nicht nur Shen-zin Su geht es schlecht, sondern dem ganzen Land jenseits der Wolken. Die Welt muss geheilt werden, und ich glaube, dass Ihr ihre Heiler sein solltet.\n\nIch möchte, dass Ihr, Ji und Aysa aufbrecht, um Eure Stärke und Weisheit in die Welt zu tragen. Die Allianz und die Horde mögen verschiedene Ideale haben, doch tief in ihrem Inneren verfolgen sie beide edle Absichten.\n\nIhr sollt selbst entscheiden, wer Euch begleiten wird.", sourceObjective = "Sprecht mit dem Geist von Meister Shang Xi und entscheidet Euch dann, ob Ihr mit der Allianz oder der Horde losziehen wollt.", sourceObjectiveStatus = "unverified-source-field" }
quests[31451] = { id = 31451, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der vermisste Händler", description = "Normalerweise kommt Händler Shi zum Kun-Lai-Gipfel, um mit den Jinyu und Grummel Geschäfte zu machen. Wir haben gehört, dass er nicht in Binan gewesen sein soll, und wir haben ihn auch hier nicht gesehen...\n\nIch mache mir Sorgen... vielleicht ist ihm ja etwas zugestoßen. Könntet Ihr am Tintenkiemenweiher nachsehen? Möglicherweise ist er ja dort.", sourceObjective = "Sprecht mit Händler Shi am Tintenkiemenweiher am Kun-Lai-Gipfel.", completion = "Mein Sohn! Sie haben mir meinen Sohn genommen... Könnt Ihr mir helfen?", sourceObjectiveStatus = "unverified-source-field" }
quests[31452] = { id = 31452, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der vermisste Händler", description = "Normalerweise kommt Händler Shi zum Kun-Lai-Gipfel, um mit den Jinyu und Grummel Geschäfte zu machen. Wir haben gehört, dass er nicht in Binan gewesen sein soll, und wir haben ihn auch hier nicht gesehen...\n\nIch mache mir Sorgen... vielleicht ist ihm ja etwas zugestoßen. Könntet Ihr am Tintenkiemenweiher nachsehen? Möglicherweise ist er ja dort.", sourceObjective = "Sprecht mit Händler Shi am Tintenkiemenweiher am Kun-Lai-Gipfel.", completion = "Mein Sohn! Sie haben mir meinen Sohn genommen... Könnt Ihr mir helfen?", sourceObjectiveStatus = "unverified-source-field" }
quests[31453] = { id = 31453, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Shado-Pan", description = "Unsere neuen Rekruten haben im Stillen über eine Gruppe Pandaren gesprochen, die sie als \"Shado-Pan\" bezeichnen. Allem Anschein nach sind sie sehr stark und geheimnisvoll.\n\nWas auch immer hier am Kun-Lai geschieht, eines steht fest: Um unsere Stellung in Pandaria zu festigen, sind wir auf ein Bündnis mit diesen Shado-Pan angewiesen.\n\nUnd genau da kommt Ihr ins Spiel. Gerüchten zufolge haben sie im Südosten eine Basis... in der Nähe von Feuerzweigwinkel.\n\nBegebt Euch dorthin und schmiert ihnen ordentlich Honig um den Bart. Für die Horde!", sourceObjective = "Sprecht mit Shado-Meister Chong am Shado-Pan-Rückzug in Feuerzweigwinkel.", completion = "Wer seid Ihr? Könnt Ihr kämpfen? Sollte dem so sein, könnten wir Eure Hilfe gebrauchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[31454] = { id = 31454, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Legende im Werden", description = "Unsere Welt steht am Scheideweg. Die nächsten paar Monate werden die Weichen für die Zukunft stellen - sollte es für uns überhaupt noch eine Zukunft geben.\n\nAch, ich greife schon wieder zu weit vor. Ich sollte wohl einen Gang zurückschalten. Kommt, trinkt mit mir. Lasst uns über die Zukunft von Azeroth sprechen.", sourceObjective = "Lasst Euch von Furorion einen ausgeben und trinkt mit ihm.", progress = "Ist alles klar?", completion = "Natürlich muss ich in dieser Angelegenheit um Eure Diskretion bitten.\n\nSchließlich wollen wir ja keine - wie soll ich sagen - weniger fähigen Leute auf den Plan rufen, als Ihr es seid.", sourceObjectiveStatus = "unverified-source-field" }
quests[31455] = { id = 31455, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Shado-Pan", description = "Unsere neuen Rekruten haben im Stillen über eine Gruppe Pandaren gesprochen, die sie als \"Shado-Pan\" bezeichnen. Allem Anschein nach sind sie sehr stark und geheimnisvoll.\n\nUnd genau da kommt Ihr ins Spiel. Gerüchten zufolge haben sie im Südosten eine Basis... in der Nähe von Feuerzweigwinkel. Reist als <Gesandter/Gesandte> der Allianz dorthin und bietet ihnen alle nur erdenkliche Unterstützung an.", sourceObjective = "Sprecht mit Shado-Meister Chong am Shado-Pan-Rückzug in Feuerzweigwinkel.", completion = "Wer seid Ihr? Könnt Ihr kämpfen? Sollte dem so sein, könnten wir Eure Hilfe gebrauchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[31456] = { id = 31456, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gehöft Moschuspranke", description = "Es gibt hier draußen noch eine weitere Siedlung der Pandaren, das Gehöft Moschuspranke. Leider weiß ich nicht, ob es ihnen gut geht - die Yaungolinvasion hat uns alle ziemlich auf Trab gehalten.\n\nIhr wart uns schon eine so große Hilfe... vielleicht könntet Ihr ja nach ihnen sehen, <mein Freund/meine Liebe>?", sourceObjective = "Reist zum Gehöft Moschuspranke am Kun-Lai-Gipfel und sprecht dort mit Lao Moschuspranke.", completion = "Was? Wer zum Henker seid Ihr? Was wollt Ihr hier?\n\nAch, Ihr wollt helfen?", sourceObjectiveStatus = "unverified-source-field" }
quests[31457] = { id = 31457, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gehöft Moschuspranke", description = "Es gibt hier draußen noch eine weitere Siedlung der Pandaren, das Gehöft Moschuspranke. Leider weiß ich nicht, ob es ihnen gut geht - die Yaungolinvasion hat uns alle ziemlich auf Trab gehalten.\n\nIhr wart uns schon eine so große Hilfe... vielleicht könntet Ihr ja nach ihnen sehen, <mein Freund/meine Liebe>?", sourceObjective = "Reist zum Gehöft Moschuspranke am Kun-Lai-Gipfel und sprecht dort mit Lao Moschuspranke.", completion = "Was? Wer zum Henker seid Ihr? Was wollt Ihr hier?\n\nAch, Ihr wollt helfen?", sourceObjectiveStatus = "unverified-source-field" }
quests[31458] = { id = 31458, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schadenskontrolle", description = "Kor'ik sendet seit Wochen Signale an die Kaiserin. Sie weiß über sämtliche Bewegungen der Klaxxi Bescheid.\n\nDas muss jetzt aufhören!\n\nKypari Ik wird als Erstes von Kor'iks Ableben erfahren. Es wäre von Vorteil für uns, wenn wir dafür sorgen könnten, dass diese Nachricht die Kaiserin nicht erreicht.\n\nDie Zerstörung der Flüsterer und des Signals dort wird uns genügend Zeit verschaffen, um einen Plan zu schmieden, ehe die Kaiserin reagieren kann.", sourceObjective = "Vernichtet 5 Flüsterer der Ik'thik und deaktiviert das Signalfeuer von Kypari Ik.", progress = "Informationen bergen Macht, Erwecker. Wer über die meisten Informationen verfügt, hat auch die meiste Macht.", completion = "Ausgezeichnete Arbeit, Erwecker! Das sollte uns die Zeit verschaffen, um den von Kor'ik angerichteten Schaden zu reparieren.\n\nDamit habt Ihr vielleicht das Blatt zu unserem Vorteil gewendet.", sourceObjectiveStatus = "unverified-source-field" }
quests[31459] = { id = 31459, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Chos Schreiben", description = "Einer der Grummel kam vorbei und sagte, Lehrensucher Cho habe nach Euch geschickt. Ihr solltet Euch mit ihm treffen, vielleicht hat er Euch ja etwas Wichtiges zu sagen.\n\nDer Grummel sagte, er sei in Einfass, Richtung Norden.", sourceObjective = "Sprecht mit Lehrensucher Cho in Einfass am Kun-Lai-Gipfel.", completion = "Oh, hallo. Schön, Euch wiederzusehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[31460] = { id = 31460, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Chos Schreiben", description = "Einer dieser putzigen kleinen Grummel kam vorbei und sagte, Lehrensucher Cho habe nach Euch geschickt. Ihr solltet Euch mit ihm treffen!\n\nDer Grummel sagte, er sei in Einfass, Richtung Norden.", sourceObjective = "Sprecht mit Lehrensucher Cho in Einfass am Kun-Lai-Gipfel.", completion = "Oh, hallo. Schön, Euch wiederzusehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[31464] = { id = 31464, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gegnerischer Fraktionsanführer besiegt" }
quests[31465] = { id = 31465, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Antworten entlocken", description = "Kypari Ik ist einer von vielen Orten, an denen der Nachwuchs von Kaiserin Shek'zeer untergebracht ist. Die Jungen sind von Geburt an waghalsig und schwer zu kontrollieren. Außerdem sind sie tödlich.\n\nSchwarmlinge kommen mit einem hochtoxischen Gift zur Welt, dessen Stärke sich mit zunehmendem Alter verringert. Das Gift setzt selbst den stärksten und fähigsten Kämpfer außer Gefecht, wenn es mit seinem Fleisch in Berührung gerät.\n\nIch möchte, dass Ihr mir etwas von diesem Gift bringt.", sourceObjective = "Sammelt 6 mit Gift überzogene Mandibeln von Schwarmlingen der Ik'thik in Kypari Ik.", progress = "Schwarmlinggift verschafft uns nicht nur eine zusätzliche Waffe, sondern wird uns auch helfen, herauszufinden, in welcher Phase sich der Schwarm befindet.", completion = "Dieses Gift befindet sich in einer fortgeschrittenen Phase, jedoch scheint es seine Wirkung nicht zu verlieren...\n\nSehr merkwürdig. Die Klaxxi wollen das bestimmt sofort erfahren. Danke, Erwecker.", sourceObjectiveStatus = "unverified-source-field" }
quests[31467] = { id = 31467, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stark wie ein Tiger", description = "Mit dem Grill könnt Ihr diese rohen Tigersteaks zu Nahrung verarbeiten, die Euch stärker macht. Lasst Euch von mir das Rezept für gegrillte Tigersteaks beibringen. Zeigt mir, was Ihr draufhabt.", sourceObjective = "Erlernt das Rezept für gegrillte Tigersteaks vom Meister des Grills und bereitet dann 5 gegrillte Tigersteaks für ihn zu.", progress = "Erlernt das Rezept von mir und zeigt mir dann, was Ihr gelernt habt.", completion = "Stärke und Gesundheit! Sie verkörpern die Wege des Grills.", sourceObjectiveStatus = "unverified-source-field" }
quests[31468] = { id = 31468, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prüfung des Schwarzen Prinzen", description = "Ich weiß aus verlässlicher Quelle, dass Ihr ein Champion unter den Champions seid, doch würde ich mich gerne selbst von Eurem Können überzeugen - wenn Ihr es gestattet.\n\nDie Mogu, die das Tal der Ewigen Blüten angegriffen haben, die Mogudiener, die in Shan'ze Dao leben, und die vom Sha verderbten Mantis, die die Schreckensöde durchstreifen... sie alle sollten eine angemessene Herausforderung für jemanden Eures Kalibers darstellen.\n\nUnd nun beweist es mir. Aber keine Eile - diese Aufgabe sollte einige Zeit in Anspruch nehmen.", sourceObjective = "Verdient Euch beim Schwarzen Prinzen einen wohlwollenden Ruf. Mogu und Mantis der Stufe 90 im Tal der Ewigen Blüten, der Tonlongsteppe und der Schreckensöde erhöhen Euren Ruf.", completion = "Wunderbar. Das ging ja richtig flott.\n\nDie Kunde von Euren vielen Leistungen ist im Tal in aller Munde!\n\nNun denn, ich werde Euch unter meine Fittiche nehmen.", sourceObjectiveStatus = "unverified-source-field" }
quests[31470] = { id = 31470, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weg des Woks", description = "Wenn Ihr Gerichte zubereiten wollt, die Eure Beweglichkeit steigern, solltet Ihr der Meisterin des Woks einige Karotten und Reis bringen. Die Shed-Ling in der Gegend tragen normalerweise viele Karotten mit sich. Wenn Ihr einen Hof habt, könnt Ihr sie auch selbst anbauen.", sourceObjective = "Bringt 5 saftigleckere Karotten zur Meisterin des Woks.", progress = "Hallo, junger Koch. Ihr wollt den Weg des Woks lernen?", completion = "Gut gemacht.", sourceObjectiveStatus = "unverified-source-field" }
quests[31471] = { id = 31471, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flink wie ein Tiger", description = "Mit dem Wok zu kochen erfordert einiges Geschick. In Eurer ersten Lektion geht es um gebratene Karotten.", sourceObjective = "Erlernt das Rezept für gebratene Karotten von der Meisterin des Woks und bereitet dann 5 Portionen für sie zu.", progress = "Lasst mich Euch beibringen, wie man gebratene Karotten zubereitet.", completion = "Gute Arbeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[31472] = { id = 31472, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weg des Topfes", description = "Die Küche des Wegs des Topfes hilft Euch, Euren Verstand zu schärfen und somit Eure Intelligenz zu erhöhen. Bringt der Meisterin des Topfes einige Jadelungenfische und sie wird Euch unterweisen. Jadelungenfische könnt Ihr im Jadewald angeln.", sourceObjective = "Bringt 5 Jadelungenfische zur Meisterin des Topfes.", progress = "Ihr wollt das Rezept für verwirbelte Nebelsuppe lernen? Dann bringt mir einige Jadelungenfische.", completion = "Sehr gut. Jetzt lasst uns mit Eurer Lektion beginnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[31473] = { id = 31473, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Stärke Eures Gegners", description = "Große Anführer haben die Macht, das Schicksal ihres Volkes zu lenken, und die Weisheit, die richtigen Entscheidungen zu treffen. Pandaria verfügt über große Macht und uralte Weisheit, doch leider findet man beide nur selten am selben Ort.\n\nWollen wir mal sehen, ob Ihr und ich daran etwas ändern können!\n\nSammelt Siegel der Macht und der Weisheit von den gefallenen Helden in himmlischen Dungeons, im Mogu'shangewölbe, im Herzen der Angst oder der Terrasse des Endlosen Frühlings. Wir werden sie sinnvoller einsetzen können als ihre gegenwärtigen Besitzer.", sourceObjective = "Sammelt 10 Siegel der Macht und 10 Siegel der Weisheit von Endbossen in himmlischen Dungeons oder von Schlachtzugsbossen im Mogu'shangewölbe, im Herzen der Angst oder auf der Terrasse des Endlosen Frühlings.", progress = "Siegel der Weisheit sind häufig bei jenen zu finden, die die arkanen Künste praktiziert haben, während Siegel der Macht üblicherweise bei jenen gefunden werden, die rohe Stärke bevorzugen.\n\nDas ist nicht immer der Fall, aber vielleicht hilft es Euch, das zu finden, was Ihr braucht.", completion = "Mein Freund - Ihr haltet, was Ihr versprecht!\n\nWir werden Eure \"Fundstücke\" gut nutzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[31474] = { id = 31474, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Suppe des Nachsinnens", description = "Während man auf den Kochtopf aufpasst, hat man sehr viel Zeit zum Nachdenken. Lasst mich Euch zeigen, wie man verwirbelte Nebelsuppe zubereitet, und Ihr werdet verstehen, was ich meine.", sourceObjective = "Erlernt das Rezept für verwirbelte Nebelsuppe vom Meister des Topfes und bereitet dann 5 Portionen Nebelsuppe für ihn zu.", progress = "Um den Weg des Topfes zu erlernen, müsst Ihr mit verwirbelter Nebelsuppe beginnen.", completion = "Die Intelligenz ist eine Gabe, die Ihr ein Leben lang verfeinern müsst.", sourceObjectiveStatus = "unverified-source-field" }
quests[31475] = { id = 31475, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weg des Dämpfens", description = "Eine feine Mahlzeit kann Eure Moral heben und Eure Willenskraft stärken, und das gilt ganz besonders für Gerichte, die nach dem Weg des Dämpfens zubereitet wurden. Bringt dem Meister des Dämpfens einige riesige Mantisgarnelen und er wird Euch unterweisen. Riesige Mantisgarnelen könnt Ihr im Meer angeln.", sourceObjective = "Bringt 5 riesige Mantisgarnelen zum Meister des Dämpfens.", progress = "Wenn Ihr den Weg des Dämpfens lernen wollt, braucht Ihr ein paar Shrimps.", completion = "Ausgezeichnete Zutaten.", sourceObjectiveStatus = "unverified-source-field" }
quests[31476] = { id = 31476, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kochen mit Liebe", description = "Wenn ich mit Dampf koche, geht meine ganze kulinarische Liebe in mein Essen über. Lasst mich Euch beibringen, wie man Garnelenklößchen zubereitet.", sourceObjective = "Erlernt das Rezept für Garnelenklößchen vom Meister des Dämpfens und bereitet dann 5 Garnelenklößchen für ihn zu.", progress = "Lasst mich Euch beibringen, wie man Garnelenklößchen zubereitet.", completion = "Gutes Essen bessert die Laune.", sourceObjectiveStatus = "unverified-source-field" }
quests[31477] = { id = 31477, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Durchhaltevermögen", description = "Es heißt, der vom Kranich ernannte Späher stünde bei seinem Schwarm mit einem Stein im Schnabel Wache. Sollte der Späher einschlafen, fällt der Stein herunter, und er wacht wieder auf. Der kunstvolle Umgang mit dem Ofen erfordert Durchhaltevermögen und Geduld. Lernt das Rezept für Wildgeflügelbraten und zeigt mir, dass Ihr das versteht.", sourceObjective = "Erlernt das Rezept für Wildgeflügelbraten von der Meisterin des Ofens und bereitet dann 5 Wildgeflügelbraten für sie zu.", progress = "Lasst Euch von mir das Rezept für Wildgeflügelbraten beibringen und dann sehen wir mal, was Ihr so draufhabt.", completion = "Ausdauer und Durchhaltevermögen sind die Voraussetzung, um alles Mögliche zu meistern. Sich an einem heißen Ofen abzurackern erfordert Geduld, die Ergebnisse sind die Mühen aber mehr als wert.", sourceObjectiveStatus = "unverified-source-field" }
quests[31478] = { id = 31478, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weg des Ofens", description = "Wenn Ihr auf der Suche nach einer herzhaften Mahlzeit seid, die Euch lange sättigt und Eure Ausdauer erhöht, solltet Ihr Euch in den Weg des Ofens einweisen lassen. Bringt der Meisterin des Ofens einige Stücke Wildgeflügelbrust und sie wird Euch unterweisen. Im Tal der Vier Winde und im Jadewald leben viele Kraniche, doch auch von anderen Vögeln könnt Ihr Wildgeflügelbrust erjagen.", sourceObjective = "Bringt 5 Stück Wildgeflügelbrust zur Meisterin des Ofens.", progress = "Wenn Ihr Wildgeflügelbraten zubereiten wollt, benötigt Ihr einige Stücke Wildgeflügelbrust.", completion = "Hiermit können wir etwas anfangen.", sourceObjectiveStatus = "unverified-source-field" }
quests[31479] = { id = 31479, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weg des Gebräus", description = "Der pandarische Weg des Gebräus produziert... nun, das lasse ich wohl am besten den Meister des Gebräus erklären. Bringt ihm ein wenig Ginseng und er wird Euch den Weg zeigen.", sourceObjective = "Bringt 1 Ginseng zum Meister des Gebräus. Ginseng kann von Sunghshin Eisentatz erworben werden.", progress = "Ihr wollt den Weg des Gebräus erlernen?", completion = "Das ist ein sehr schöner Ginseng. Wollt Ihr lernen, wie man daraus Tee kocht?", sourceObjectiveStatus = "unverified-source-field" }
quests[31480] = { id = 31480, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tut Euch was Gutes", description = "Meine Geschwister sind immer so ernst. Ich finde, das Leben ist viel zu kurz, um die ganze Zeit ernst zu sein. Trinkt doch einen Schluck Ginsengtee mit mir. Ich werde Euch zeigen, wie man ihn zubereitet.", sourceObjective = "Erlernt das Rezept für Ginsengtee vom Meister des Gebräus und bereitet dann 1 Tee für ihn zu.", progress = "Lasst mich Euch beibringen, wie man Ginsengtee zubereitet.", completion = "Sehr gut. Der Tee ist köstlich.", sourceObjectiveStatus = "unverified-source-field" }
quests[31481] = { id = 31481, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Furcht selbst", description = "Während meiner Zeit hier habe ich die eine oder andere Pandarenweisheit aufgeschnappt. Ganz besonders gefällt mir diese hier:\n\n\"Die Furchtsamen bekommen Angst, bevor es Probleme gibt, die Feiglinge verspüren sie, wenn es Probleme gibt. Die Tapfersten unter uns spüren die Angst erst, nachdem die Probleme beseitigt wurden.\"\n\nIst das wirklich so? Wir werden es bald erfahren.\n\nDas Sha der Angst ist zur Terrasse des Endlosen Frühlings geflohen. Verfolgt es, besiegt es, und reißt ihm den Geist aus, sofern es einen hat.\n\nEuer Mut soll stattlich belohnt werden.", sourceObjective = "Besiegt das Sha der Angst auf der Terrasse des Endlosen Frühlings und holt Euch die Schimäre der Angst.", progress = "Noch eine Pandarenweisheit: \"Die Angst ist kein Verbrecher, der eingesperrt werden muss, sondern ein Lehrmeister, den wir verstehen müssen.\" Nur wenn wir uns unseren Ängsten stellen, werden wir auch stärker.\n\nHabt Ihr Euch schon den Euren gestellt, {name}?", completion = "Ihr habt es geschafft!\n\nManche mögen ja auf Magie oder Stahl vertrauen, doch nach meiner Erfahrung ist die Angst die mächtigste Waffe, die man führen kann. Setzt sie gekonnt ein, und Eure Gegner werden gar nicht erst gegen Euch kämpfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[31482] = { id = 31482, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Atem des Schwarzen Prinzen", description = "<Furorions durchdringende rote Augen haben Euch fest im Blick.>\n\nSolche wie Euch findet man nur selten, {name}.\n\nIhr seid genau, wonach ich suchte: Eine Person mit dem Potenzial, Ereignisse auf weltweiter Ebene zu beeinflussen.\n\nKommt nun, ich versprach Euch eine Belohnung, und die sollt Ihr auch haben! Östlich von dieser Höhle liegt eine Reihe steinerner Treppen, die zu einem Aussichtspunkt führen, den die Einheimischen \"Des Steinmetz' Torheit\" getauft haben. Trefft Euch dort mit mir.", sourceObjective = "Geht bis ans obere Ende der Steintreppe bei des Steinmetz' Torheit und holt Euch bei Furorion Eure Belohnung ab.", progress = "Wir treffen uns vor der Taverne bei des Steinmetz' Torheit.", completion = "Ihr habt Euch das verdient, {name}! Nutzt es mit Bedacht.\n\nBitte versteht, dass ich die Schulden meines Vaters zu begleichen beabsichtige. Ich werde ALLES daran setzen, diese Welt zu verteidigen. Wenn Ihr in Zukunft jemals Zweifel haben solltet, dürft Ihr jederzeit meine Mittel in Frage stellen, niemals aber meine Absichten. Die Sicherheit dieser Welt hat für mich oberste Priorität.\n\nNun denn, lasst uns über die aktuellen Geschehnisse sprechen.", sourceObjectiveStatus = "unverified-source-field" }
quests[31483] = { id = 31483, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unheil im Verzug", description = "Der Feldzug der Pandaren hat gerade erst begonnen! Wir wenden unsere Aufmerksamkeit nun dem fortwährenden Konflikt zwischen der Allianz und der Horde zu.\n\nMeine Kontaktpersonen in Rabenholdt berichten mir, dass die 7. Legion der Allianz und eine beachtliche Invasionsstreitmacht der Horde sich der Südküste Pandarias nähern. Ob es uns nun gefällt oder nicht: Pandaria könnte schon bald zu einem Schlachtfeld werden.\n\nFürs Erste sind wir hier fertig, aber ich möchte, dass Ihr Euch bei mir meldet, wenn die Flotte eintrifft. Dann... werden wir gemeinsam in Aktion treten!", sourceObjective = "Setzt Euch mit Furorion in Verbindung, wenn Eure Kriegsflotte die Südküste von Pandaria erreicht hat.", completion = "Sie sind da!\n\n<Furorion klatscht in die Hände und reibt sie aufgeregt zusammen.>\n\nAch, {name}. Jetzt wird es spannend.", sourceObjectiveStatus = "unverified-source-field" }
quests[31486] = { id = 31486, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alles, was ich übers Kochen weiß", description = "Ich bin so froh, dass Euch mein Essen schmeckt. Wärt Ihr vielleicht an den Rezepten interessiert? Falls ja, solltet Ihr sie aus erster Hand von meinen Lehrern vom Halbhügelmarkt lernen. Alles, was ich über die Küche weiß, habe ich bei ihnen gelernt.\n\nUnd wenn Ihr sowieso in diese Gegend kommt, könntet Ihr dann vielleicht Sungshin Eisentatz diese Nachricht überbringen? Sie war meine Lieblingslehrerin. Ich vermisse sie, und ich möchte, dass sie das auch weiß.", sourceObjective = "Überbringt Sungshin Eisentatz den Brief. Sie unterrichtet auf dem Halbhügelmarkt.", progress = "Ihr habt einen Brief für mich?", completion = "Oh, wie aufmerksam. Ich höre immer sehr gerne von meinen ehemaligen Schülern.", sourceObjectiveStatus = "unverified-source-field" }
quests[31487] = { id = 31487, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Misstöne", description = "Mit Schallgeflüster die Kunchong zu manipulieren war nur die allererste Phase meiner Forschungen und doch scheint es, als ob das Reich diese Technik vollständig übernommen hat. Die Manipulatoren der Shek'zeer sind zu ungeduldig, eine gebührliche Verbindung mit ihren Kunchong einzugehen.\n\nIhre Faulheit wird sie teuer zu stehen kommen.\n\nSchlagt die Stimmgabel nahe der Schreckenskunchong in den Gelegen an und seht, wie sie vor Verwirrung taumeln und ihre Herren angreifen werden. Nutzt diesen Vorteil aus und macht ihnen den Garaus.", sourceObjective = "Tötet 4 Schreckenskunchong und 6 Shek'zeer Manipulatoren in den Gelegen von Shek'zeer. Die Stimmgabel der Verwirrung wird die Kunchong verwirren und schwächen.", completion = "Möge Euch dies eine Mahnung sein. Die Kunchong sollte man sowohl fürchten als auch respektieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[31488] = { id = 31488, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fremd in einem fremden Land", description = "Verzeihung, {class}. Heißt Ihr {name}?\n\nEine Gestalt in einem dunklen Umhang hat mich gebeten, Euch das hier zu geben. Es war eine Reisende von hinter den Nebeln so wie Ihr, aber - nun, ich habe ihr nicht getraut.\n\nDie Nachricht kommt von einer Taverne an der Verhüllten Treppe. Ich gebe Euch die Nachricht, aber... Ihr solltet auf Euch achtgeben, wenn Ihr Euch dort hinaufwagt!", sourceObjective = "Sucht den \"Schwarzen Prinzen\" in der Taverne im Nebel an der Verhüllten Treppe auf.", progress = "Dann hat meine Nachricht also ihren Weg zu Euch gefunden!", completion = "Meine Leute haben ihren Auftrag erfüllt und Euch zu mir gebracht. Wunderbar.", sourceObjectiveStatus = "unverified-source-field" }
quests[31489] = { id = 31489, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fremd in einem fremden Land", description = "Verzeihung, {class}. Heißt Ihr {name}?\n\nEine Gestalt in einem dunklen Umhang hat mich gebeten, Euch das hier zu geben. Es war eine Reisende von hinter den Nebeln so wie Ihr, aber - nun, ich habe ihr nicht getraut.\n\nSie erwähnte den Namen \"Furorion\". Könnt Ihr damit etwas anfangen?\n\nIch gebe Euch die Nachricht, aber... Ihr solltet auf Euch achtgeben, wenn Ihr mit diesen Leuten zu tun habt.", sourceObjective = "Sucht Furorion in der Taverne im Nebel an der Verhüllten Treppe auf.", progress = "So sieht man sich wieder!", completion = "Meine Leute haben ihren Auftrag erfüllt und Euch zu mir gebracht. Wunderbar.", sourceObjectiveStatus = "unverified-source-field" }
quests[31490] = { id = 31490, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gegen das Fußvolk", description = "Das Wichtigste zuerst: Wir müssen dringend einige Kreuzfahrer loswerden.\n\nUnd wenn ich davon spreche, den Scharlachroten Kreuzzug loszuwerden, meine ich, ihn auszulöschen: ALLE Kreuzfahrer bis hinunter in die untersten Dienstränge!", sourceObjective = "Tötet 50 Mitglieder des Scharlachroten Kreuzzugs in den Scharlachroten Hallen.", completion = "Ein guter Anfang, {name}!\n\nJetzt dauert es nicht mehr lange, bis der Scharlachrote Kreuzzug nur noch eine hässliche Fußnote der Geschichte sein wird.", sourceObjectiveStatus = "unverified-source-field" }
quests[31492] = { id = 31492, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Fackel der Stärke", description = "Xuen hat sich eine Aufgabe ausgedacht, die dazu dienen soll, die \"Stärke zu verfeinern\". Ich glaube allmählich, dass der Begriff \"Stärke\" für ihn eine andere Bedeutung hat als für den Rest von uns.\n\nHier, bringt diese Fackel auf die Tore des Tempels. Wenn Ihr das schafft, ohne dass die Fackel erlischt, habt Ihr die Aufgabe bestanden.\n\nSetzt Euch aber auf keinen Fall mit der Fackel auf ein Reittier. Dann geht sie aus. Das könnt Ihr mir ruhig glauben.", sourceObjective = "Tragt die Fackel der Stärke zu den Toren des Tempels des Weißen Tigers, ohne dass sie erlischt.", completion = "Alle Achtung! Ihr habt's geschafft! Ich scheitere meist an einer dieser Windböen.", sourceObjectiveStatus = "unverified-source-field" }
quests[31493] = { id = 31493, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Im Namen von Sicherheit und Ordnung", description = "Hier in den Hallen gibt es ein Buch, das großen Wert für mich hat.\n\nAber leider befindet es sich im Besitz von Flammenwirker Koegler. Ich habe schon mehrmals versucht, in seine Nähe zu kommen, aber es hat nie funktioniert.\n\nVielleicht habt Ihr ja mehr Glück. Aber passt auf Euch auf: Ich habe gehört, dass er komplett wahnsinnig geworden sein soll. Der Flammenwirker plant, alle Bücher der Bibliothek zu verbrennen.\n\nWahrscheinlich wird er dabei gleich die Scharlachroten Hallen selbst niederbrennen.", sourceObjective = "Holt Euch den Kodex des Kreuzzugs.", progress = "Ich muss unbedingt diesen Kodex in meinen Besitz bringen.", completion = "Ah, da ist er ja!\n\n<Die vermummte Kreuzfahrerin reibt sich beim Anblick des Kodex voller Vorfreude die Hände.>\n\nUnd jetzt habe ich eine Namensliste aller Mitglieder des Scharlachroten Kreuzzugs!\n\nNur für den Fall, dass jemand nicht ordnungsgemäß gelistet ist. Ich halte in solchen Dingen gerne Ordnung.", sourceObjectiveStatus = "unverified-source-field" }
quests[31494] = { id = 31494, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ihren Fängen entronnen", description = "Die Manipulatoren der Shek'zeer sperren junge Kunchong in das Gelege und setzen sie reinen Furchtenergien aus, die sie korrumpieren und ihr Wachstum beschleunigen.\n\nAbscheulich! Das lasse ich nicht zu!\n\nBrecht die Käfige auf und entlasst die Jungtiere in die Freiheit.", sourceObjective = "Brecht Kunchongkäfige auf, um 8 Kunchongjungtiere in den Gelegen von Shek'zeer freizulassen.", completion = "Ja, ich konnte sehen, wie sie sich erhoben. Ein wunderschöner Anblick!", sourceObjectiveStatus = "unverified-source-field" }
quests[31495] = { id = 31495, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gegen das Fußvolk", description = "Das Wichtigste zuerst: Wir müssen dringend einige Kreuzfahrer loswerden.\n\nUnd wenn ich davon spreche, den Scharlachroten Kreuzzug loszuwerden, meine ich, ihn auszulöschen: ALLE Kreuzfahrer bis hinunter in die untersten Dienstränge!", sourceObjective = "Tötet 50 Mitglieder des Scharlachroten Kreuzzugs in den Scharlachroten Hallen.", completion = "Ein guter Anfang, {name}!\n\nJetzt dauert es nicht mehr lange, bis der Scharlachrote Kreuzzug nur noch eine hässliche Fußnote der Geschichte sein wird.", sourceObjectiveStatus = "unverified-source-field" }
quests[31496] = { id = 31496, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Kostprobe vom Feinsten", description = "Die Wunder des Kyparisaftes versetzen mich immer wieder in Erstaunen. Neben seinen zahlreichen Eigenschaften und Anwendungen lässt sich der Saft zu einem nahrhaften und äußerst aromatischen Elixier verfeinern.\n\nIhr werdet nirgendwo im Reich eine exquisitere Zubereitung dieses Gebräus finden als im Palast selbst. Gewiss finden sich doch in den Heimen der Getreuen Zapfstellen, die bis zum Rand mit diesem süßen Nektar gefüllt sind.\n\nFüllt mir diesen Krug an den Zapfstellen und bringt ihn mir. Ich sehne mich danach, das kaiserliche Ambrosia noch einmal zu schmecken.", sourceObjective = "Benutzt das Harzgefäß an den kaiserlichen Zapfstellen vor dem Herzen der Angst viermal, um es zu füllen.", completion = "Ah, ja, gebt her! Schnell! Meine Vorderbeine zittern vor Erwartung.", sourceObjectiveStatus = "unverified-source-field" }
quests[31497] = { id = 31497, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Im Namen von Sicherheit und Ordnung", description = "Hier in den Hallen gibt es ein Buch, das großen Wert für mich hat.\n\nAber leider befindet es sich im Besitz von Flammenwirker Koegler. Ich habe schon mehrmals versucht, in seine Nähe zu kommen, aber es hat nie funktioniert.\n\nVielleicht habt Ihr ja mehr Glück. Aber passt auf Euch auf: Ich habe gehört, dass er komplett wahnsinnig geworden sein soll. Der Flammenwirker plant, alle Bücher der Bibliothek zu verbrennen.\n\nWahrscheinlich wird er dabei gleich die Scharlachroten Hallen selbst niederbrennen.", sourceObjective = "Holt Euch den Kodex des Kreuzzugs.", progress = "Ich muss unbedingt diesen Kodex in meinen Besitz bringen.", completion = "Ah, da ist er ja!\n\n<Die vermummte Kreuzfahrerin reibt sich beim Anblick des Kodex voller Vorfreude die Hände.>\n\nUnd jetzt habe ich eine Namensliste aller Mitglieder des Scharlachroten Kreuzzugs!\n\nNur für den Fall, dass jemand nicht ordnungsgemäß gelistet ist. Ich halte in solchen Dingen gerne Ordnung.", sourceObjectiveStatus = "unverified-source-field" }
quests[31498] = { id = 31498, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Herausforderungsmodus der Jadeschlange - Trostpreis (Nter)" }
quests[31499] = { id = 31499, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Herausforderungsmodus der Jadeschlange - Bronze (Nter)" }
quests[31500] = { id = 31500, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Herausforderungsmodus der Jadeschlange - Silber (Nter)" }
quests[31501] = { id = 31501, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Herausforderungsmodus der Jadeschlange - Gold (Nter)" }
quests[31502] = { id = 31502, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gestutzte Flügel", description = "Die jungen Flieger dieser Ära sind faszinierend. Über ihre außergewöhnliche Wendigkeit und Ausdauer verfügten zu meiner Zeit nur unglaublich geschickte oder erfahrene Flieger.\n\nDas würde auf eine Art der Evolution in der Flügelstruktur hindeuten... Oder vielleicht eine Weiterentwicklung in der Ausbildung? Herbeigeführte genetische Mutation? Selektive Züchtung?\n\nAch! Ohne Gewebeproben lässt sich das unmöglich mit Gewissheit sagen.\n\nBringt mir ihre Flügel! Und versucht sie dabei nicht zu ruinieren, ja? Ich brauche sie intakt!", sourceObjective = "Sammelt 24 Nadlerflügel von Nadlern der Shek'zeer in den Gelegen von Shek'zeer.", progress = "Habt Ihr die Proben?", completion = "Hervorragend, sie sind in erstklassigem Zustand.", sourceObjectiveStatus = "unverified-source-field" }
quests[31503] = { id = 31503, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abkürzung zum Ruin", description = "Unter den Getreuen gibt es einen Champion, Vesswache Na'kal, dessen Stärke nicht aus seiner Erfahrung oder Entwicklung herrührt, sondern aus genetischer Modifikation. Er sollte als Musterbeispiel für die Zukunft der Mantis dienen - für die kranke Vorstellung, dass wir stark geboren werden könnten, ohne selbst etwas dazu zu tun.\n\nEr ist eine Pervertierung meiner Arbeit! Die Genverbesserung war AUSSCHLIESSLICH für reife Veteranen gedacht, die den Schwarm bereits hinter sich gelassen haben!\n\nVernichtet ihn. Vielleicht lernt Großkaiserin Shek'zeer daraus, dass Abkürzungen zum Ruin führen.", sourceObjective = "Tötet Vesswache Na'kal vor dem Herzen der Angst.", completion = "Meine Verbesserungen sind Werkzeuge für erfahrene Krieger und keine Spielzeuge für diese törichten Kinder!", sourceObjectiveStatus = "unverified-source-field" }
quests[31504] = { id = 31504, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abrüstung", description = "Wenn die Agenten der Großkaiserin noch nach den Sicherheitsstandards meiner Zeit arbeiten, werden sie überall in den Gelegen gewaltige Pheromonminen versteckt haben.\n\nDiese könnte sie durch ein bloßes Flüstern alle gleichzeitig hochgehen lassen, um den Palast einzuhüllen und ganzen Belagerungsarmeen die Kräfte zu rauben.\n\nWenn wir bei einer größeren Konfrontation auf Erfolg hoffen wollen, müssen wir die Minen entschärfen. Mein... \"Geschenk\" an Euch, als wir uns begegneten, wird Euch in die Lage versetzen, die Minen zu sehen. Löst sie aus und begebt Euch in eine sichere Entfernung.", sourceObjective = "Schaltet 8 Pheromonminen rund um die Gelege von Shek'zeer und das Herz der Angst aus.", completion = "Ihr wart den Pheromonen doch nicht ausgesetzt? Das könnte nämlich zu... ach, was soll ich Euch mit Details beunruhigen.", sourceObjectiveStatus = "unverified-source-field" }
quests[31505] = { id = 31505, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vesswachenpflichten", description = "Vesswache Vik'az koordiniert die Verteidigungstruppen in Zan'vess. Er ist im Kampf so viel wert wie zehn Mantis, und seine Gegenwart inspiriert die Zan'thik, die an seiner Seite kämpfen.\n\nIch brauche wohl kaum zu erwähnen, dass wir ihn tot sehen wollen.\n\nEr patrouilliert in dem Siedlungsbereich im Zentrum der Insel.", sourceObjective = "Tötet Vesswache Vik'az in Zan'vess.", completion = "Ihre Champions fallen einer nach dem anderen.", sourceObjectiveStatus = "unverified-source-field" }
quests[31506] = { id = 31506, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fesseln der Manipulation", description = "Die Zan'thik verfügen über eine ganze Armee von... Arbeitsverpflichteten.\n\nYaungol tragen spezielle Fesseln, die die Auswirkungen von Schallmanipulationen verstärken und verlängern. Nur dank dieser Technik können die Manipulatoren der Zan'thik solch eine große Zahl an Knechten kontrollieren, die unaufhörlich in den Steinbrüchen für sie schuften müssen.\n\nDiese Fesseln würde ich gern untersuchen.", sourceObjective = "Sammelt 6 Fesseln der Zan'thik von gedankengefesselten Minenarbeitern und gedankengefesselten Schlägern in Zan'vess.", progress = "Das werdet Ihr doch schaffen, nicht wahr?", completion = "Wirklich ausgeklügelte Vorrichtungen. Ich habe das Gefühl, die werden sich noch als nützlich erweisen.", sourceObjectiveStatus = "unverified-source-field" }
quests[31507] = { id = 31507, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kernschmelze", description = "Die Giftstecherskorpione auf Zan'vess werden schon von klein auf mit Saft ernährt, der eine faszinierende Mutation bewirkt, bei der ihr natürlicher Panzer von Bern durchdrungen wird. Das ist nichts anderes als organisches Kyparit - die gleiche Substanz, die zum Schmieden der meisten Waffen und Rüstungen des Reiches verwendet wird.\n\nIch glaube, ich habe eine Methode gefunden, Kyparit chemisch aufzuschließen, aber sie muss noch getestet werden. Setzt diese Granaten gegen die Giftstecher der Zan'thik ein und beobachtet die Ergebnisse.", sourceObjective = "Tötet 6 Giftstecher der Zan'thik in Zan'vess. Setzt Korvens experimentelle Granate ein, um ihren Panzer zu durchdringen.", completion = "Das Kyparit hat sich also entzündet? Faszinierend!\n\nNicht ganz das, worauf ich gehofft hatte, aber immerhin.", sourceObjectiveStatus = "unverified-source-field" }
quests[31508] = { id = 31508, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Probenanforderung", description = "Kyparitwürmer können sich extrem gut anpassen, um ihre Umwelt zu imitieren. Sie können außerdem auf eine gewaltige Größe anwachsen, und das in einem Tempo, das für die meisten Kreaturen unerhört ist.\n\nIhre Physiologie könnte wertvolle Einblicke in weitere Mutationen bieten.\n\nBringt mir Splitterproben von Kyparitkriechern in den Untiefen bei Zan'vess.", sourceObjective = "Sammelt 6 Kyparitsplitter von Kyparitkriechern im Salzigen Schlick.", progress = "Habt Ihr die Proben?", completion = "Na seht an, Ihr habt es tatsächlich geschafft. Ich war schon fast darauf gefasst, Eure Reste mit einem Krug aus dem Schlamm schöpfen zu müssen.", sourceObjectiveStatus = "unverified-source-field" }
quests[31509] = { id = 31509, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verwurzelte Furcht", description = "Die Folgen von Shek'zeers Wahnsinn werden noch lange nach dem Ende ihrer Herrschaft zu spüren sein. Wir werden noch viele Jahre damit zu kämpfen haben, unser Land zu heilen, und am Ende werden sich unsere Bemühungen womöglich doch als nutzlos erweisen.\n\nEine neue Spezies von Sha-verderbter Flora hat begonnen, in der Nähe von Zan'vess Wurzeln zu schlagen. Vernichtet alle Pflanzen, die Ihr findet, aber nehmt Euch in Acht – man kann nie wissen, welch unheilvolle Verteidigungsmechanismen sie haben mögen.", sourceObjective = "Vernichtet 15 Furchtsporenknollen in Zan'vess und im Salzigen Schlick.", completion = "Eine interessante Spezies, aber die Risiken, sie zu Studienzwecken zu behalten, sind zu groß.", sourceObjectiveStatus = "unverified-source-field" }
quests[31510] = { id = 31510, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jetzt ist Ruhe", description = "In der südwestlichen Ecke von Zan'vess liegen die Flüsternden Steine. Ähnlich wie die Türme hier sind sie für die Übertragung von Schallsignalen über weite Entfernungen sehr wichtig.\n\nEin Gehilfe der Kaiserin bedient die Steine und sorgt so für eine Verbindung zwischen ihr und den Truppen der Zan'thik. Unterbrecht das Signal und bringt ihn dann zum Schweigen.", sourceObjective = "Macht Euch an dem Resonanzkristall der Zan'thik bei den Flüsternden Steinen in Zan'vess zu schaffen, um den Gehilfen Sek'ot zu reizen, und tötet ihn.", completion = "Den Kontakt zu Zan'vess zu verlieren, muss sie weiter in den Verfolgungswahn und Wahnsinn treiben.\n\nGut. Soll sie leiden.", sourceObjectiveStatus = "unverified-source-field" }
quests[31511] = { id = 31511, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein historischer Moment", description = "Ich trommle die anderen Taurenpilger zusammen und wir reisen gemeinsam ins Tal.\n\nTrefft mich am Tor der Himmlischen Erhabenen im Süden des Kun-Lai-Gipfels und sprecht dort mit mir.", sourceObjective = "Sprecht mit Sonnenläufer Dezco am Tor der Himmlischen Erhabenen.", completion = "Danke, dass Ihr so schnell zur Stelle seid.\n\nJahrtausende lang hat der Goldene Lotus das Tal vor den Zugriffen jener, die vom Hunger nach seiner Macht getrieben wurden, bewahrt.\n\nLeider sind diese Zeiten vorbei, und wir brauchen Eure Hilfe.", sourceObjectiveStatus = "unverified-source-field" }
quests[31512] = { id = 31512, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein historischer Moment", description = "Die Himmlischen Erhabenen gewähren uns erneut Zugang zum Tal! Das wird ein unvergesslicher Anblick sein.\n\nWir sollten keine Zeit verlieren. Geht zum Tor der Himmlischen Erhabenen im Süden des Kun-Lai-Gipfels und sprecht dort mit mir.", sourceObjective = "Sprecht mit Anduin Wrynn am Tor der Himmlischen Erhabenen.", completion = "Danke, dass Ihr so schnell zur Stelle seid.\n\nJahrtausende lang hat der Goldene Lotus das Tal vor den Zugriffen jener, die vom Hunger nach seiner Macht getrieben wurden, bewahrt.\n\nLeider sind diese Zeiten vorbei, und wir brauchen Eure Hilfe.", sourceObjectiveStatus = "unverified-source-field" }
quests[31513] = { id = 31513, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Klingen des Gesalbten", description = "Das Problem mit dem Scharlachroten Kreuzzug ist, dass seine Kreuzfahrer selbst nach dem Tod immer wiederkehren.\n\nHinter diesen Wiederbelebungen steckt die Hochinquisitorin Weißsträhne. Ihr Tod wäre das Ende des Kreuzzuges.\n\nUm sie endgültig ins Jenseits zu schicken, benötigen wir zwei legendäre Schwerter, jedes von ihnen mit einer lange verschollenen Geschichte.\n\nZum Glück für mich... äh, ich meine uns... befinden sich diese Klingen des Gesalbten hier irgendwo im Kloster.\n\nFindet sie und stoßt sie in Weißsträhnes Leichnam, nachdem Ihr sie getötet habt. Dadurch ist ihr Tod endgültig.", sourceObjective = "Findet die zwei Klingen des Gesalbten.", progress = "<Nachdem Ihr das eine Schwert eingesammelt habt, wendet Ihr Euch der Suche nach dem zweiten zu.>\n\n<Auf der Statue hinter dem Schwert befindet sich eine Inschrift: \"Die Hand der Vorsehung\".>", completion = "<Die zweite gesalbte Klinge schwebt vor der nassen Statue. Dampf steigt vom Schwert auf.>\n\n<Ihr habt das ungute Gefühl, dass die Hand der Vorsehung auf Euch gewartet hat.>", sourceObjectiveStatus = "unverified-source-field" }
quests[31514] = { id = 31514, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Und zum Staub werdet Ihr zurückkehren", description = "<Ihr nehmt die zweite Klinge des Gesalbten in die Hand und fühlt, wie Euch die Kraft der beiden Schwerter durchströmt.>\n\n<Aber es bleibt noch eins zu tun: Wie Euch die mysteriöse Frau mit der Kapuze erklärte, müssen beide Schwerter in den Leichnam der Hochinquisitorin Weißsträhne gestoßen werden, um den Scharlachroten Kreuzzug ein für alle Mal zu besiegen.>", sourceObjective = "Durchbohrt mit den Klingen des Gesalbten den Leichnam der Hochinquisitorin Weißsträhne, um sie endgültig zu töten.", completion = "Jetzt wo Weißsträhne endgültig tot ist, ist auch der Kreuzzug am Ende. Es ist nur noch eine Frage der Zeit, bis wir seinen Widerstand gebrochen haben werden.\n\nIch danke Euch, {name}. Nicht nur um meiner selbst willen, sondern auch im Namen aller, die diesem fanatischen Hass ausgesetzt waren.\n\nUnd danke auch für die beiden Schwerter. Durch ihr Blut aufs Neue gesalbt, werden sie mir im Kampf gegen Dunkelmeister Gandling in Scholomance gute Dienste leisten.\n\nUnd jetzt möchte ich mich von Euch verabschieden.", sourceObjectiveStatus = "unverified-source-field" }
quests[31515] = { id = 31515, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Klingen des Gesalbten", description = "Das Problem mit dem Scharlachroten Kreuzzug ist, dass seine Kreuzfahrer selbst nach dem Tod immer wiederkehren.\n\nHinter diesen Wiederbelebungen steckt die Hochinquisitorin Weißsträhne. Ihr Tod wäre das Ende des Kreuzzuges.\n\nUm sie endgültig ins Jenseits zu schicken, benötigen wir zwei legendäre Schwerter, jedes von ihnen mit einer lange verschollenen Geschichte.\n\nZum Glück für mich... äh, ich meine uns... befinden sich diese Klingen des Gesalbten hier irgendwo im Kloster.\n\nFindet sie und stoßt sie in Weißsträhnes Leichnam, nachdem Ihr sie getötet habt. Dadurch ist ihr Tod endgültig.", sourceObjective = "Findet die zwei Klingen des Gesalbten.", progress = "<Nachdem Ihr das eine Schwert eingesammelt habt, wendet Ihr Euch der Suche nach dem zweiten zu.>\n\n<Auf der Statue hinter dem Schwert befindet sich eine Inschrift: \"Die Hand der Vorsehung\".>", completion = "<Die zweite gesalbte Klinge schwebt vor der nassen Statue. Dampf steigt vom Schwert auf.>\n\n<Ihr habt das ungute Gefühl, dass die Hand der Vorsehung auf Euch gewartet hat.>", sourceObjectiveStatus = "unverified-source-field" }
quests[31516] = { id = 31516, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Und zum Staub werdet Ihr zurückkehren", description = "<Ihr nehmt die zweite Klinge des Gesalbten in die Hand und fühlt, wie Euch die Kraft der beiden Schwerter durchströmt.>\n\n<Aber es bleibt noch eins zu tun: Wie Euch die mysteriöse Frau mit der Kapuze erklärte, müssen beide Schwerter in den Leichnam der Hochinquisitorin Weißsträhne gestoßen werden, um den Scharlachroten Kreuzzug ein für alle Mal zu besiegen.>", sourceObjective = "Durchbohrt mit den Klingen des Gesalbten den Leichnam der Hochinquisitorin Weißsträhne, um sie endgültig zu töten.", completion = "Jetzt wo Weißsträhne endgültig tot ist, ist auch der Kreuzzug am Ende. Es ist nur noch eine Frage der Zeit, bis wir seinen Widerstand gebrochen haben werden.\n\nIch danke Euch, {name}. Nicht nur um meiner selbst willen, sondern auch im Namen aller, die diesem fanatischen Hass ausgesetzt waren.\n\nUnd danke auch für die beiden Schwerter. Durch ihr Blut aufs Neue gesalbt, werden sie mir im Kampf gegen Dunkelmeister Gandling in Scholomance gute Dienste leisten.\n\nUnd jetzt möchte ich mich von Euch verabschieden.", sourceObjectiveStatus = "unverified-source-field" }
quests[31517] = { id = 31517, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rabaukenkampf", description = "Hier achten wir Stärke, nicht Brutalität. Es ist bedauerlich, dass sich so mancher auf meiner Türschwelle einfindet, dem diese Unterscheidung unklar ist.\n\nIch habe einen solchen Herausforderer abgewiesen. Aus Rache ist er über das Dorf Yinying hergefallen.\n\nGeht nach Yinying, südlich des Tempels, und stellt Euch diesem \"Shonuf\".", sourceObjective = "Besiegt Shonuf.", completion = "Ich preise Euren Sieg und danke Euch, dass Ihr mir diesen Grobian vom Hals geräumt habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[31518] = { id = 31518, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Tal der Ewigen Blüten", description = "Es sind viele Lebensalter vergangen, seit die Tore zum Tal offen standen, {name}.\n\nDas würde ich um alles in der Welt nicht verpassen wollen, und Ihr solltet das auch nicht!\n\nTrefft mich am Südrand des Kun-Lai-Gipfels. Ich werde dort auf Euch warten.", sourceObjective = "Sprecht mit Anduin am Tor der Himmlischen Erhabenen.", sourceObjectiveStatus = "unverified-source-field" }
quests[31519] = { id = 31519, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine würdige Herausforderung: Yan-Zhu der Dekantierte", description = "{name}, Ihr müsst eine beherzte Gruppe zusammenstellen und sie in die Brauerei Sturmbräu führen. Aktiviert die Kugel des Herausforderers und helft Yan-Zhu dem Dekantierten, sich zu verdünnisieren.\n\nKehrt zu mir zurück, wenn Ihr diese Herausforderung bestanden habt, und ich werde Euch fürstlich belohnen.", sourceObjective = "Schließt die Brauerei Sturmbräu im Herausforderungsmodus ab.", sourceObjectiveStatus = "unverified-source-field" }
quests[31520] = { id = 31520, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine würdige Herausforderung: Sha des Zweifels", description = "{name}, Ihr müsst eine beherzte Gruppe zusammenstellen und sie in den Tempel der Jadeschlange führen. Aktiviert die Kugel des Herausforderers und vernichtet das Sha des Zweifels.\n\nKehrt zu mir zurück, wenn Ihr diese Herausforderung bestanden habt, und ich werde Euch fürstlich belohnen.", sourceObjective = "Schließt den Tempel der Jadeschlange im Herausforderungsmodus ab.", completion = "Mein Dank ist Euch gewiss, {name}. Ihr habt heute großen Mut an den Tag gelegt und die Herausforderung in Windeseile bewältigt. Eure Freunde werden beeindruckt und Eure Gegner verängstigt sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[31521] = { id = 31521, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pflichten eines Meisters", description = "Es wird der Tag kommen, an dem Ihr alles gemeistert haben werdet, was wir Euch beizubringen haben. An jenem Tag ist es Zeit für Euch, andere etwas zu lehren. Wenn Ihr unter Beweis gestellt habt, dass Ihr alle Wege gemeistert habt, kommt zurück und redet mit mir.", sourceObjective = "Bereitet Rippchen mit schwarzem Pfeffer und Garnelen, Küstennebelreisnudeln, Fischeintopf nach Moguart, Gedämpfte Krabbe, Chun-Tian-Frühlingsrollen und ein wahnsinniges Brauerfrühstück zu und kehrt dann zur Weiserin der Wege zurück.", completion = "Ihr wart ein sehr guter Schüler. Nun solltet Ihr Euer Wissen an andere weitergeben. Ich hoffe, Ihr redet mit dem Vorratsmeister und nehmt so früh wie möglich einen Lehrling an.", sourceObjectiveStatus = "unverified-source-field" }
quests[31522] = { id = 31522, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine würdige Herausforderung: Sha des Hasses", description = "{name}, Ihr müsst eine abgeklärte Gruppe zusammenstellen und sie ins Shado-Pan-Kloster führen. Aktiviert die Kugel des Herausforderers und rettet Taran Zhu vor dem Sha des Hasses.\n\nKehrt zu mir zurück, wenn Ihr diese Herausforderung bestanden habt, und ich werde Euch fürstlich belohnen.", sourceObjective = "Schließt das Shado-Pan-Kloster im Herausforderungsmodus ab.", sourceObjectiveStatus = "unverified-source-field" }
quests[31523] = { id = 31523, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine würdige Herausforderung: Xin der Waffenmeister", description = "{name}, Ihr müsst eine geschickte Gruppe zusammenstellen und sie in den Mogu'shanpalast führen. Aktiviert die Kugel des Herausforderers und bereitet Xin dem Waffenmeister ein Ende.\n\nKehrt zu mir zurück, wenn Ihr diese Herausforderung bestanden habt, und ich werde Euch fürstlich belohnen.", sourceObjective = "Schließt den Mogu'shanpalast im Herausforderungsmodus ab.", completion = "Vielen Dank, {name}. Eure Kampfkunst sucht ihresgleichen, und Eure Eilfertigkeit wird die Herzen Eurer Widersacher mit Furcht erfüllen.", sourceObjectiveStatus = "unverified-source-field" }
quests[31524] = { id = 31524, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine würdige Herausforderung: Raigonn", description = "{name}, Ihr müsst eine entschlossene Gruppe zusammenstellen und sie zum Tor der Untergehenden Sonne führen. Aktiviert die Kugel des Herausforderers und vernichtet Raigonn.\n\nKehrt zu mir zurück, wenn Ihr diese Herausforderung bestanden habt, und ich werde Euch fürstlich belohnen.", sourceObjective = "Schließt das Tor der Untergehenden Sonne im Herausforderungsmodus ab.", sourceObjectiveStatus = "unverified-source-field" }
quests[31525] = { id = 31525, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine würdige Herausforderung: Schwadronsführer Ner'onok", description = "{name}, Ihr müsst eine scharfsichtige Gruppe zusammenstellen und sie zur Belagerung des Niuzaotempels führen. Aktiviert die Kugel des Herausforderers und bringt Schwadronsführer Ner'onok zu Boden.\n\nKehrt zu mir zurück, wenn Ihr diese Herausforderung bestanden habt, und ich werde Euch fürstlich belohnen.", sourceObjective = "Schließt den Niuzaotempel im Herausforderungsmodus ab.", sourceObjectiveStatus = "unverified-source-field" }
quests[31526] = { id = 31526, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine würdige Herausforderung: Durand", description = "{name}, Ihr müsst eine tapfere Gruppe zusammenstellen und sie in das Scharlachrote Kloster führen. Aktiviert die Kugel des Herausforderers und zerschmettert Durand mit gerechtem Zorn.\n\nKehrt zu mir zurück, wenn Ihr diese Herausforderung bestanden habt, und ich werde Euch fürstlich belohnen.", sourceObjective = "Schließt das Scharlachrote Kloster im Herausforderungsmodus ab.", sourceObjectiveStatus = "unverified-source-field" }
quests[31527] = { id = 31527, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine würdige Herausforderung: Flammenwirker Koegler", description = "{name}, Ihr müsst eine gewitzte Gruppe zusammenstellen und sie in die Tiefen der Scharlachroten Hallen führen. Aktiviert die Kugel des Herausforderers und setzt dem bücherverbrennenden Treiben von Flammenwirker Koegler ein Ende.", sourceObjective = "Schließt die Scharlachroten Hallen im Herausforderungsmodus ab.", sourceObjectiveStatus = "unverified-source-field" }
quests[31528] = { id = 31528, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine würdige Herausforderung: Dunkelmeister Gandling", description = "{name}, Ihr müsst eine furchtlose Gruppe zusammenstellen und sie in die Tiefen von Scholomance führen. Aktiviert die Kugel des Herausforderers und reinigt Scholomance von der finsteren Präsenz von Dunkelmeister Gandling.\n\nKehrt zu mir zurück, wenn Ihr diese Herausforderung bestanden habt, und ich werde Euch fürstlich belohnen.", sourceObjective = "Schließt Scholomance im Herausforderungsmodus ab.", sourceObjectiveStatus = "unverified-source-field" }
quests[31529] = { id = 31529, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mission: Eindämmung der Shed-Ling", description = "Ich wurde in dieses Tal entsandt, um das Kernland vor allen möglichen Bedrohungen zu verteidigen.\n\nUnd ich habe ein vordringliches Ziel ausgemacht. Die Shed-Ling der Sprungschweife haben sich in die Bergklippen hoch über dem Ackerland eingegraben.\n\nWenn sich niemand um sie kümmert, werden sie sich rasend schnell vermehren und schon bald auf den Feldern unten auftauchen.\n\nSie müssen ausgelöscht werden.", sourceObjective = "Tötet 12 Shed-Ling der Sprungschweife.", completion = "Die Ziele sind ausgelöscht? Gut gemacht, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[31530] = { id = 31530, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mission: Ho-zen-Eindämmung", description = "Seit meiner Ankunft hier habe ich die Ho-zen beobachtet. Und das Muster ihrer Aktivitäten im Lager gefällt mir ganz und gar nicht.\n\nIm Schutze der Nacht steigen mehrere Ho-zen vom Berg hinunter in das Ackerland im Tal, um Vorräte zu rauben.\n\nWir müssen diese Diebeszüge aufhalten. Ich habe bei jeder sich mir bietenden Gelegenheit einige von ihnen ausgeschaltet, aber ein Soldat allein ist nicht genug.\n\nIch benötige Eure Hilfe. Tötet ganz einfach so viele Ho-zen wie möglich.", sourceObjective = "Tötet 12 Ho-zen von Kunzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[31531] = { id = 31531, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mission: Bedrohung aus der Luft", description = "Ich habe ein weiteres, möglicherweise gefährliches Ziel ausgemacht, das wohl den meisten anderen Personen entgangen wäre.\n\nDie Klippensegler über den Hügeln im Osten stellen eine ernsthafte Gefahr dar.\n\nIch konnte beobachten, wie sie sich auf die Felder der Bauern stürzen und Getreide und Samen schnappen, wenn niemand hinschaut.\n\nUm die Höfe zu beschützen, müssen wir einige von ihnen ausschalten.", sourceObjective = "Tötet 12 Klippensegler.", completion = "Ich wusste, dass Ihr diesen Auftrag problemlos erfüllen würdet. Gut gemacht, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[31532] = { id = 31532, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mission: König der Raubvögel", description = "Auf meiner täglichen Routinepatrouille durch die Berge habe ich heute Morgen einen riesigen, weißen Vogel entdeckt, der auf die Felder niederstieß.\n\nEr hat sich ein voll ausgewachsenes Yak gekrallt und ist damit in den Klippen verschwunden.\n\nHeute war es ein Yak, aber morgen könnte es einen Landarbeiter treffen!\n\nWir müssen diesen Vogel ausschalten, bevor er sich ein neues Opfer suchen kann.", sourceObjective = "Tötet den großen Klippenfalken.", completion = "Ihr habt es tatsächlich geschafft, {name}?! Ich bin sehr erleichtert, dass das Tal dank Eures Einsatzes wieder etwas sicherer ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[31534] = { id = 31534, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das erste Bräu", description = "Könnt Ihr ein Geheimnis bewahren, {name}?\n\nIch habe mich mit dem Brauen beschäftigt. Ich habe zwar nur diese alte, handgefertigte Brauanlage, aber sie funktioniert noch ganz ordentlich.\n\nUnd ich habe eine Idee für ein neues Braurezept. Allerdings fehlen mir dazu ein paar Zutaten.\n\nIch selbst bin ja leider furchtbar schüchtern, aber ich habe gesehen, wie viele Freunde Ihr schon unter den Leuten hier gefunden habt.\n\nKönntet Ihr nicht vielleicht einige Zutaten von den Bauern für mich besorgen?", sourceObjective = "Besorgt 1 süße Teichmelone von Haohan Lehmkrall, 1 flaumigen Pfirsich von Gina Lehmkrall, 1 Portion schwarze Kirschen von Fischi Rohrroder und 1 roten Rettich von Bauer Fung.", progress = "Ich weiß nicht, wie ich auf die Idee gekommen bin... Vielleicht ist es, weil ich die ganze Zeit auf diese Brauerei starre... Aber ich will das beste Bier des ganzen Tales, nein, von Pandaria brauen!\n\nOh, was für ein naiver Traum, oder?", completion = "Ihr habt sie! Das ist ja wundervoll, {name}!\n\nIch werde so schnell wie möglich mit dem Brauen anfangen.", sourceObjectiveStatus = "unverified-source-field" }
quests[31535] = { id = 31535, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auffüllen der Speisekammer", description = "Aus ganz Pandaria kommen die Leute, um von der Familie Eisentatz kochen zu lernen. Wir sind sehr stolz darauf, die besten Köche zu stellen, und auch darauf, unser Wissen weitergeben zu können. Aus diesem Grund verlangen wir nur sehr wenig für unseren Kochunterricht.\n\nDas bedeutet jedoch auch, dass wir oft einen Mangel an Zutaten für die Unterrichtsstunden haben. Wärt Ihr bereit, etwas der Schule zu spenden, um den Schülern zu helfen, die nicht genug Geld haben?", sourceObjective = "Bringt Nam Eisentatz ein Bündel mit Zutaten. Bündel mit Zutaten werden mithilfe von Behältern hergestellt, die von Händler Cheng verkauft werden.", progress = "Es ist schwierig, kochen zu lernen, wenn man keine Zutaten hat.", completion = "Wir wissen Eure Hilfe sehr zu schätzen. Dies ist für einige unserer Schüler eine große Hilfe.", sourceObjectiveStatus = "unverified-source-field" }
quests[31536] = { id = 31536, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Konservierung der Frische", description = "Damit Kochzutaten so frisch wie möglich bleiben, müssen sie stets richtig gelagert werden. Zum Glück verkauft Händler Cheng dort drüben gute Behälter. Ich will Euch ja nur ungern eine so anspruchslose Aufgabe auftragen, aber könntet Ihr vielleicht einen leeren Tigerfleischkorb für mich kaufen?", sourceObjective = "Bringt Nam Eisentatz einen leeren Tigerfleischkorb.", progress = "Zutaten verderben, wenn sie nicht korrekt gelagert werden.", completion = "Ah, das ist gut. Jetzt werden diese Zutaten frisch bleiben, bis wir bereit sind zu kochen.", sourceObjectiveStatus = "unverified-source-field" }
quests[31537] = { id = 31537, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ellas Kostprobe", description = "So, jetzt ist mein Bräu endlich fertig. Aber um zu wissen, ob es auch etwas taugt, muss jemand es kosten.\n\nWürdet Ihr vielleicht mein Bräu nehmen und herausfinden, was die Leute in Halbhügel dazu sagen?\n\nIch... Ich selbst traue mich nicht.", sourceObjective = "Fragt Jogu den Betrunkenen, Bobo Eisentatz, Bauer Yoon und Nana Lehmkrall, was sie von Ellas Bräu halten.", progress = "Ich finde, mein Bräu schmeckt ziemlich wild. Aber das ist meine persönliche Meinung. Ich brauche noch ein paar andere Urteile darüber.", completion = "Wirklich? Das haben sie wirklich gesagt? Unglaublich!", sourceObjectiveStatus = "unverified-source-field" }
quests[31538] = { id = 31538, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein guter Tropfen", description = "Jetzt fehlt nur noch eine Person, die mein Bräu kosten muss.\n\nUnd diese Person soll weit gereist und Getränke in der ganzen Welt verkostet haben.\n\nEr ist gerade vor Ort und ich würde gern wissen, was er von meinen Fähigkeiten hält.", sourceObjective = "Bittet Chen Sturmbräu, Ellas Bräu zu kosten.", completion = "Ihr wollt mich doch nicht etwa auf den Arm nehmen, oder, {name}? Wenn er das wirklich gesagt hat, heißt das... dass ich etwas vom Brauen verstehe!\n\nIch danke Euch, {name}. Ihr habt mir wirklich geholfen, zu etwas Selbstvertrauen zu finden.", sourceObjectiveStatus = "unverified-source-field" }
quests[31539] = { id = 31539, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Frage der Schönheit", description = "Wir leben in einer Welt der Magie. Die Wenigen unter uns, die über eine große Begabung verfügen, können die Dinge, die wir fertigen, mit dieser Magie versehen und ihnen Kräfte verleihen. Solche Dinge werden hoch geschätzt.\n\nDoch die noch größere Ausnahme sind die Personen, die Dinge schaffen, die über mehrere Zeitalter hinweg geschätzt werden - nicht weil sie über Kräfte verfügen, sondern wegen ihrer herausragenden Schönheit.\n\nDer Tempel der Jadeschlange hat uns mit solch einem Werk beauftragt, und ich glaube, Ihr seid einer der Würdigsten unter uns. Nehmt Ihr den Auftrag an?", sourceObjective = "Fertigt ein Auftragsgemälde an und bringt es zu Tintenmeister Wei im Arboretum im Jadewald. Das Rezept findet Ihr in Eurem Inschriftenkundemenü unter \"Quests\".", sourceObjectiveStatus = "unverified-source-field" }
quests[31540] = { id = 31540, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stäbe für das Tiankloster", description = "Wie es scheint, werden im Tiankloster dieses Jahr viele Mönche ausgebildet. Wir haben einen riesigen Auftrag für Stäbe erhalten. Und mit riesig meine ich wirklich RIESIG.\n\nKönntet Ihr einen Teil des Auftrags übernehmen? Das würde ich sehr zu schätzen wissen. Ihr werdet natürlich die Belohnungen für Euren Anteil erhalten.", sourceObjective = "Fertigt 3 Geistereisenstäbe und 2 Regenmohnstäbe. Bringt sie zu Tintenmeister Wei im Arboretum im Jadewald.", sourceObjectiveStatus = "unverified-source-field" }
quests[31541] = { id = 31541, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In Jade gemeißelt", description = "Meister Kwang ist einer der größten Dichter unserer Zeit. Er hat ein wunderschönes Gedicht geschrieben, und eine Händlerin in Halbhügel hätte gerne diese Worte in Stein gemeißelt, um sie stolz in ihrem Zuhause ausstellen zu können. Sie will, dass jemand mit den besten Fähigkeiten damit beauftragt wird. Würdet Ihr diesen Auftrag annehmen?", sourceObjective = "Fertigt eine gravierte Jadescheibe und bringt sie zu Tintenmeister Jo Po im Arboretum im Jadewald. Das Rezept findet Ihr in Eurem Inschriftenmenü unter \"Quests\".", progress = "Wie läuft es?", completion = "Wunderschön. Das wird mit Sicherheit Gefallen finden.", sourceObjectiveStatus = "unverified-source-field" }
quests[31542] = { id = 31542, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fleischfarbene Tinte", description = "Die Kalligrafie ist ein uralter Brauch in Pandaria. Ich arbeite an einem Werk über einen uralten Krieg, und ich suche nach einer Tinte, die für das Thema geeignet ist.\n\nIch habe wirklich fast überall nach dem richtigen Farbton gesucht, aber ich kann ihn einfach nirgends finden. Fällt Euch vielleicht eine Möglichkeit ein, an die Farbe zu kommen, die ich benötige?", sourceObjective = "Um die von Tintenmeister Glenzu gewünschte Farbe zu erhalten, sind Pigmente aus einer ungewöhnlichen Quelle erforderlich. Seine Beschreibung lässt vor Eurem geistigen Auge die Farbe des Blutes erscheinen -der von Tigerblut, um genau zu sein...\n\n Stellt 5 Einheiten Fleischfarbene Tinte her. Das Rezept findet Ihr in Eurem Inschriftenkundemenü unter \"Quests\".", progress = "Ich kann einfach nicht die richtige Farbe finden!", completion = "Wo habt Ihr... Wie habt Ihr... Das ist ja perfekt!", sourceObjectiveStatus = "unverified-source-field" }
quests[31543] = { id = 31543, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Porträt einer Dame", description = "Viele große Kunstwerke sind das Ergebnis einer großen Liebe. Ein Händler in Halbhügel würde gerne ein Porträt als Geburtstagsgeschenk für seine geliebte Frau anfertigen lassen. Wollt Ihr diesen Auftrag annehmen?", sourceObjective = "Malt ein Porträt von Madame Goya und bringt es zu Tintenmeister Glenzu im Arboretum im Jadewald. Das Rezept findet Ihr in Eurem Inschriftenmenü unter \"Quests\".", sourceObjectiveStatus = "unverified-source-field" }
quests[31544] = { id = 31544, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Tribut den Toten", description = "Alles hat einmal ein Ende. Sogar das Leben eines guten Mannes. Eine Familie am Kun-Lai hat ein Monument für ihren geliebten Patriarchen, der vor Kurzem aus dem Leben geschieden ist, in Auftrag gegeben. Nehmt Ihr den Auftrag an?", sourceObjective = "Fertigt einen Beschriebenen Monumentstein an und bringt ihn zu Tintenmeister Jo Po im Arboretum im Jadewald. Das Rezept findet Ihr in Eurem Inschriftenkundemenü unter \"Quests\".", progress = "Die Toten zu respektieren, ist Teil unserer Traditionen.", completion = "Ein großartiges Werk zu Ehren eines großartigen Mannes.", sourceObjectiveStatus = "unverified-source-field" }
quests[31545] = { id = 31545, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die schönen Dinge im Leben", description = "Die Pandarianische Schatzsuchervereinigung ist daran interessiert, fachmännisch gefertigte Ware von fähigen Juwelenschleifern, wie Ihr es seid, zu kaufen. Die Artikel werden katalogisiert, und die außergewöhnlichsten Schliffe werden in einer geheimen Schatzkammer aufbewahrt, während der Rest verkauft wird, um unsere Kasse aufzufüllen.\n\nUnser Ziel ist es, schließlich eine einzigartige Kollektion für ein besonderes Ereignis zu kreieren.", sourceObjective = "Bringt die angeforderten Waren zu einem Mitglied der Pandarianischen Schatzsuchervereinigung im Tal der Ewigen Blüten.", sourceObjectiveStatus = "unverified-source-field" }
quests[31548] = { id = 31548, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erste Erfahrungen", description = "Nachdem Ihr jetzt zum Ausbilden von Tieren qualifiziert seid, ist es Zeit, Eure Fähigkeiten unter Beweis zu stellen!\n\nZieht ins Tal und stellt Euch einem Kampfhaustier. Wenn Ihr gewonnen habt, kommt wieder zu mir, dann setze ich Eure Ausbildung fort. Viel Glück!", sourceObjective = "Gewinnt einen Kampf mit einem Haustier.", sourceObjectiveStatus = "unverified-source-field" }
quests[31549] = { id = 31549, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf dem Wege der Besserung", description = "Nachdem Ihr nun einen Kampf gewonnen habt, müssen wir Eure Haustiere heilen, damit sie wieder einsatzbereit sind! Sucht unsere Stallmeisterin Shelby Steinsplint auf, um Eure Haustiere zu heilen und wiederzubeleben.", sourceObjective = "Heilt Eure Haustiere vollständig, indem Ihr Shelby Steinsplint die Stallmeisterin aufsucht.", sourceObjectiveStatus = "unverified-source-field" }
quests[31550] = { id = 31550, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hab' eins!", description = "So weit, so gut, {name}! Wenn Ihr so weitermacht, macht Euch bei dem ganzen Haustierkram bald keiner mehr was vor. Jetzt solltet Ihr auch mal ein eigenes Haustier fangen!\n\nZieht wieder los, sucht Euch ein Kampfhaustier, gegen das Ihr kämpfen könnt, greift es an und werft Eure Falle, sobald seine Gesundheit niedrig genug ist. Dann bringt mir Euren Fang zur Begutachtung.\n\nUnd immer dran denken: Ihr braucht mindestens ein Haustier der Stufe 3, um Eure Falle verwenden zu können!", sourceObjective = "Fangt ein Kampfhaustier.", completion = "Aha... eine hervorragende Wahl. Ihr seid auf dem besten Weg, Euch ein tolles Team aufzubauen!\n\nDenkt daran: Ihr habt die Möglichkeit, jedes Haustier zu fangen, gegen das Ihr kämpfen könnt, also holt Euch im Laufe Eurer Abenteuer so viele wie möglich.", sourceObjectiveStatus = "unverified-source-field" }
quests[31551] = { id = 31551, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hab' eins!", description = "So weit, so gut, {name}! Wenn Ihr so weitermacht, macht Euch bei dem ganzen Haustierkram bald keiner mehr was vor. Jetzt solltet Ihr auch mal ein eigenes Haustier fangen!\n\nZieht wieder los, sucht Euch ein Kampfhaustier, gegen das Ihr kämpfen könnt, greift es an und werft Eure Falle, sobald seine Gesundheit niedrig genug ist. Dann bringt mir Euren Fang zur Begutachtung.\n\nUnd immer dran denken: Ihr braucht mindestens ein Haustier der Stufe 3, um Eure Falle verwenden zu können!", sourceObjective = "Fangt ein Kampfhaustier.", sourceObjectiveStatus = "unverified-source-field" }
quests[31552] = { id = 31552, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erste Erfahrungen", description = "Nachdem Ihr jetzt zum Ausbilden von Tieren qualifiziert seid, ist es Zeit, Eure Fähigkeiten unter Beweis zu stellen!\n\nZieht in den Wald und stellt Euch einem Kampfhaustier. Wenn Ihr gewonnen habt, kommt wieder zu mir, dann setze ich Eure Ausbildung fort. Viel Glück!", sourceObjective = "Gewinnt einen Kampf mit einem Haustier.", sourceObjectiveStatus = "unverified-source-field" }
quests[31553] = { id = 31553, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf dem Wege der Besserung", description = "Nachdem Ihr nun einen Kampf gewonnen habt, müssen wir Eure Haustiere heilen, damit sie wieder einsatzbereit sind! Sucht unsere Stallmeisterin Seriadne auf, um Eure Haustiere zu heilen und wiederzubeleben.", sourceObjective = "Heilt Eure Haustiere vollständig, indem Ihr Seriadne die Stallmeisterin aufsucht.", sourceObjectiveStatus = "unverified-source-field" }
quests[31555] = { id = 31555, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hab' eins!", description = "So weit, so gut, {name}! Wenn Ihr so weitermacht, macht Euch bei dem ganzen Haustierkram bald keiner mehr was vor. Jetzt solltet Ihr auch mal ein eigenes Haustier fangen!\n\nZieht wieder los, sucht Euch ein Kampfhaustier, gegen das Ihr kämpfen könnt, greift es an und werft Eure Falle, sobald seine Gesundheit niedrig genug ist. Dann bringt mir Euren Fang zur Begutachtung.\n\nUnd immer dran denken: Ihr braucht mindestens ein Haustier der Stufe 3, um Eure Falle verwenden zu können!", sourceObjective = "Fangt ein Kampfhaustier.", sourceObjectiveStatus = "unverified-source-field" }
quests[31556] = { id = 31556, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erste Erfahrungen", description = "Nachdem Ihr jetzt zum Ausbilden von Tieren qualifiziert seid, ist es Zeit, Eure Fähigkeiten unter Beweis zu stellen!\n\nZieht in die Wildnis und stellt Euch einem Kampfhaustier. Wenn Ihr gewonnen habt, kommt wieder zu mir, dann setze ich Eure Ausbildung fort. Viel Glück!", sourceObjective = "Gewinnt einen Kampf mit einem Haustier.", completion = "Gut gemacht, {name}! Ihr könnt mit diesen Haustieren besser umgehen, als ich dachte!", sourceObjectiveStatus = "unverified-source-field" }
