quests[31589] = { id = 31589, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf dem Wege der Besserung", description = "Nachdem Ihr nun einen Kampf gewonnen habt, müssen wir Eure Haustiere heilen, damit sie wieder einsatzbereit sind! Sucht unseren Stallmeister Murog auf, um Eure Haustiere zu heilen und wiederzubeleben.", sourceObjective = "Heilt Eure Haustiere vollständig, indem Ihr Murog den Stallmeister aufsucht.", progress = "Geht es Euren Haustieren besser?", completion = "Jetzt strotzen Eure Haustiere ja nur so vor Gesundheit, {name}. Denkt daran, Ihr könnt all Eure Haustiere jederzeit heilen und wiederbeleben lassen, indem Ihr einen Stallmeister aufsucht.", sourceObjectiveStatus = "unverified-source-field" }
quests[31590] = { id = 31590, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hab' eins!", description = "So weit, so gut, {name}! Wenn Ihr so weitermacht, macht Euch bei dem ganzen Haustierkram bald keiner mehr was vor. Jetzt solltet Ihr auch mal ein eigenes Haustier fangen!\n\nZieht wieder los, sucht Euch ein Kampfhaustier, gegen das Ihr kämpfen könnt, greift es an und werft Eure Falle, sobald seine Gesundheit niedrig genug ist. Dann bringt mir Euren Fang zur Begutachtung.\n\nUnd immer dran denken: Ihr braucht mindestens ein Haustier der Stufe 3, um Eure Falle verwenden zu können!", sourceObjective = "Fangt ein Kampfhaustier.", progress = "Habt Ihr eins erwischt?", completion = "Aha... eine hervorragende Wahl. Ihr seid auf dem besten Weg, Euch ein tolles Team aufzubauen!\n\nDenkt daran: Ihr könnt jedes Haustier fangen, gegen das Ihr kämpfen könnt, also holt Euch im Laufe Eurer Abenteuer so viele wie möglich.", sourceObjectiveStatus = "unverified-source-field" }
quests[31591] = { id = 31591, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erste Erfahrungen", description = "Nachdem Ihr jetzt zum Ausbilden von Tieren qualifiziert seid, ist es Zeit, Eure Fähigkeiten unter Beweis zu stellen!\n\nZieht in die Wildnis und stellt Euch einem Kampfhaustier. Wenn Ihr gewonnen habt, kommt wieder zu mir, dann setze ich Eure Ausbildung fort. Viel Glück!", sourceObjective = "Gewinnt einen Kampf mit einem Haustier.", completion = "Gut gemacht, {name}! Ihr könnt mit diesen Haustieren besser umgehen, als ich dachte!", sourceObjectiveStatus = "unverified-source-field" }
quests[31592] = { id = 31592, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf dem Wege der Besserung", description = "Nachdem Ihr nun einen Kampf gewonnen habt, müssen wir Eure Haustiere heilen, damit sie wieder einsatzbereit sind! Sucht unsere Stallmeisterin Jenova Steinschild auf, um Eure Haustiere zu heilen und wiederzubeleben.", sourceObjective = "Heilt Eure Haustiere vollständig, indem Ihr Jenova Steinschild die Stallmeisterin aufsucht.", completion = "Jetzt strotzen Eure Haustiere ja nur so vor Gesundheit, {name}. Denkt daran, Ihr könnt all Eure Haustiere jederzeit heilen und wiederbeleben lassen, indem Ihr einen Stallmeister aufsucht.", sourceObjectiveStatus = "unverified-source-field" }
quests[31593] = { id = 31593, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hab' eins!", description = "So weit, so gut, {name}! Wenn Ihr so weitermacht, macht Euch bei dem ganzen Haustierkram bald keiner mehr was vor. Jetzt solltet Ihr auch mal ein eigenes Haustier fangen!\n\nZieht wieder los, sucht Euch ein Kampfhaustier, gegen das Ihr kämpfen könnt, greift es an und werft Eure Falle, sobald seine Gesundheit niedrig genug ist. Dann bringt mir Euren Fang zur Begutachtung.\n\nUnd immer dran denken: Ihr braucht mindestens ein Haustier der Stufe 3, um Eure Falle verwenden zu können!", sourceObjective = "Fangt ein Kampfhaustier.", completion = "Aha... eine hervorragende Wahl. Ihr seid auf dem besten Weg, Euch ein tolles Team aufzubauen!\n\nDenkt daran: Ihr könnt jedes Haustier fangen, gegen das Ihr kämpfen könnt, also holt Euch im Laufe Eurer Abenteuer so viele wie möglich.", sourceObjectiveStatus = "unverified-source-field" }
quests[31598] = { id = 31598, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kypa'raks Kern", description = "<Als der Ringwurm auseinanderbricht, fällt aus seinem Innersten ein gewaltiger Klumpen organischen Kyparits heraus. Das wird jemand in Klaxxi'vess sehen wollen.>", sourceObjective = "Bringt den massiven Kyparitkern zu Bernschmied Zikk in Klaxxi'vess.\n\nBereitgestellter Gegenstand:", completion = "Interessant. Es war klug von Euch, die Bedeutung dieser Angelegenheit zu erkennen, Erwecker. Organisches Kyparit ist sehr wertvoll für uns.\n\nHier, eine Belohnung. Ein fairer Tausch.", sourceObjectiveStatus = "unverified-source-field" }
quests[31599] = { id = 31599, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Schlund der Matriarchin", description = "<Die gewaltigen Mandibeln der Kunchongmatriarchin Karanosh dürften irgendwem in Klaxxi'vess etwas wert sein.>", sourceObjective = "Bringt die enormen Kunchongmandibeln zu Bernschmied Zikk in Klaxxi'vess.\n\nBereitgestellter Gegenstand:", completion = "Ich erkenne diese Mandibeln. Karanosh hat nämlich meinen Bruder gefressen.\n\nAber schließlich habe ich Millionen von Brüdern.\n\n<Zikk lacht gackernd.>", sourceObjectiveStatus = "unverified-source-field" }
quests[31600] = { id = 31600, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Szenarien ermöglichen" }
quests[31603] = { id = 31603, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Saat der Angst", progress = "Einige der verderbten Kypari wurden während des schrecklichen Marsches des Schwarms verstreut. Dabei verteilten sie Splitter des Sha-infizierten Berns übers Land.\n\nBringt mir alles, was Ihr davon auf Euren Reisen finden könnt, damit es entsorgt werden kann.", completion = "So lange wie diese Splitter das Land bedecken wird unsere Heimat ein Ort der Angst und des Todes sein." }
quests[31605] = { id = 31605, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Zan'thikausgrabung", description = "Wir haben auf Zan'vess soeben eine Nachricht von einem Gehilfen abgefangen. Dort haben Yaungolarbeiter im Berntagebau auf der Rückseite der Insel einen Getreuen ausgegraben.\n\nBegebt Euch sofort dorthin und befreit ihn, bevor ihn die Zan'thik vernichten!", sourceObjective = "Sucht den ausgegrabenen Getreuen im Berntagebau auf Zan'vess.", completion = "<Diese Mantis scheint erst kürzlich aus ihrer Kammer gebrochen worden zu sein. Sie hustet trocken.>\n\n... Se... zier...er... ist... zurück...", sourceObjectiveStatus = "unverified-source-field" }
quests[31606] = { id = 31606, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Sezierer erwacht", description = "Ihr seid... nicht wie die anderen...\n\nIch kann den Ruf der Klaxxi hören... <hust>\n\nIch brauche nur einen Augenblick.", sourceObjective = "Wehrt die Zan'thik ab, während Rik'kal erwacht.", progress = "<Hust, Hust>\n\nMein Kopf...", completion = "Seht Euch nur an! So viele verschiedene Teile, ja... und alle so gut im Töten. Faszinierend.\n\nIch muss unbedingt mal Euer Gehirn anzapfen... Muhahaha.", sourceObjectiveStatus = "unverified-source-field" }
quests[31609] = { id = 31609, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Zorn von Shek'zeer", description = "Die anderen befreiten Getreuen sind über das Herz der Angst verstreut und wehren den Mantisschwarm ab. Sie brauchen möglicherweise Eure Hilfe!", sourceObjective = "Fügt dem Mantisschwarm eine vernichtende Niederlage zu, indem Ihr Akkolon, Shox'tik, die Manifestation des Terrors und 25 unterworfene Mantis tötet.", completion = "Die Belagerung ist gebrochen, zumindest für jetzt.", sourceObjectiveStatus = "unverified-source-field" }
quests[31611] = { id = 31611, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Kun-Lai-Hammer", description = "Habt Ihr schon mal das Braumondfest erlebt?\n\nDie freundlichen Leute von Binan veranstalten da ein ordentliches Fest. Und die Festivitäten des heutigen Abends werden in Sachen Getränke von niemand anderem beliefert als von mir hier höchstpersönlich.\n\nIch braue meinen berühmten Kun-Lai-Hammer!\n\nWollt Ihr vielleicht vorbeikommen und ein wenig mitfeiern? Das sollte ein vollkommen entspannendes Ereignis werden, ohne irgendeine Form von Gefahr.", sourceObjective = "Beschützt das Braumondfest.", completion = "Ich scheine die Gefahren des Brauens dieser Tage unterschätzt zu haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[31612] = { id = 31612, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schatten des Kaiserreichs", description = "Ihr versteht unseren Orden nur teilweise. Als <Außenstehender/Außenstehende> seid Ihr entsprechend behandelt worden.\n\nEs ist nicht mehr länger angemessen, dass wir unsere Geheimnisse vor Euch verbergen. Es gibt da etwas, das Ihr sehen solltet.", sourceObjective = "Begleitet Kil'ruk den Windschnitter in die Kammer unterhalb von Klaxxi'vess.", progress = "Es gibt da etwas, das Ihr sehen solltet.", completion = "<Kil'ruk sieht Euch merkwürdig an.>\n\nDie Klaxxi'va werden Euch vielleicht nie ganz akzeptieren. Ihre fremdenfeindliche Einstellung schließt die Möglichkeit aus, dass ein {race} nützlich sein könnte.\n\nIch jedenfalls bin stolz, an Eurer Seite gekämpft haben zu dürfen, {class}. Eure Anwesenheit und Eure Hilfe sind uns eine große Ehre.", sourceObjectiveStatus = "unverified-source-field" }
quests[31613] = { id = 31613, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brisantes Grünsteinbräu", description = "Ich arbeite an einer Ladung meines berühmten brisanten Grünsteinbräus.\n\nSollte sich hervorragend dafür eignen, mit den Strolchen und den schelmischen Elementaren aufzuräumen, die wir in letzter Zeit in der Nähe der Minen gesehen haben.\n\nIch sag Euch was, wie wär's, wenn Ihr ein paar Eurer Freunde zusammentrommelt und sie herbringt, um etwas davon auszuprobieren?\n\nDie erste Runde geht aufs Haus!", sourceObjective = "Helft bei der Verteidigung von Grünstein.", progress = "Geister, Jadezerstörer, Steine, die sprechen. Diese Welt wird langsam ein beunruhigender Ort.\n\nAber... das ist nichts, was nicht mit einem starken Gebräu und einem einnehmenden Lächeln gelöst werden kann.\n\nUnd natürlich einem ordentlichen rechten Haken, oder auch zweien.", completion = "Ich sehe, Ihr habt mein brisantes Grünsteinbräu bereits sinnvoll angewendet. Gut gemacht, {class}!", sourceObjectiveStatus = "unverified-source-field" }
quests[31614] = { id = 31614, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Täglicher zufälliger, heroischer Dungeon (Erster) (Mists)" }
